&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/clickhouse-rs&#34;&gt;clickhouse-rs&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Search&lt;/td&gt;
&lt;td&gt;OpenSearch&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-opensearch&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/opensearch&#34;&gt;opensearch&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Search&lt;/td&gt;
&lt;td&gt;Elasticsearch&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-elasticsearch&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/elasticsearch&#34;&gt;elasticsearch&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Graph&lt;/td&gt;
&lt;td&gt;Neo4j&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-neo4j&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/neo4rs&#34;&gt;neo4rs&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Graph&lt;/td&gt;
&lt;td&gt;NebulaGraph&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-nebulagraph&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;nebula-client&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Graph&lt;/td&gt;
&lt;td&gt;ArangoDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-arangodb&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/arangors&#34;&gt;arangors&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Time series&lt;/td&gt;
&lt;td&gt;InfluxDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-influxdb&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/influxdb2&#34;&gt;influxdb2&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Time series&lt;/td&gt;
&lt;td&gt;Apache IoTDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-iotdb&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;iotdb-client-rs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Time series&lt;/td&gt;
&lt;td&gt;QuestDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-questdb&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;questdb-rs (ILP)&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;blockquote&gt;
&lt;p&gt;Every data backend goes through a unified trait abstraction (&lt;code&gt;RdbmsClient&lt;/code&gt; / &lt;code&gt;Cache&lt;/code&gt; / &lt;code&gt;SearchClient&lt;/code&gt; / &lt;code&gt;GraphClient&lt;/code&gt; / &lt;code&gt;TsdbClient&lt;/code&gt;); pull in the matching contrib crate as needed.&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;Project-Structure&#34;&gt;&lt;a href=&#34;#Project-Structure&#34; class=&#34;headerlink&#34; title=&#34;Project Structure&#34;&gt;&lt;/a&gt;Project Structure&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;e-cat/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat/                       # core: App lifecycle&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport/             # transport abstraction (Server trait)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport-http/        # axum implementation&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport-grpc/        # tonic implementation&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-middleware/            # tower::Layer middleware&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-protos/                # Protobuf definitions&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-errors/                # error code system&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-metadata/              # metadata propagation&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-encoding/              # serialization abstraction&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-logging/               # tracing integration&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-registry/              # service registry and discovery&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-config/                # configuration management&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-metrics/               # Prometheus integration&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-data/                  # data access traits&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-security/              # attack detection (security-rust)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-cli/                   # CLI tool&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                       # design docs and implementation plans&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── examples/                   # example projects&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;Quick-Start&#34;&gt;&lt;a href=&#34;#Quick-Start&#34; class=&#34;headerlink&#34; title=&#34;Quick Start&#34;&gt;&lt;/a&gt;Quick Start&lt;/h2&gt;&lt;h3 id=&#34;Prerequisites&#34;&gt;&lt;a href=&#34;#Prerequisites&#34; class=&#34;headerlink&#34; title=&#34;Prerequisites&#34;&gt;&lt;/a&gt;Prerequisites&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;Rust 1.80+ (stable toolchain)&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/protocolbuffers/protobuf&#34;&gt;protoc&lt;/a&gt; (the Protocol Buffers compiler)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Install-the-CLI&#34;&gt;&lt;a href=&#34;#Install-the-CLI&#34; class=&#34;headerlink&#34; title=&#34;Install the CLI&#34;&gt;&lt;/a&gt;Install the CLI&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;cargo install ecat-cli&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Create-a-Service&#34;&gt;&lt;a href=&#34;#Create-a-Service&#34; class=&#34;headerlink&#34; title=&#34;Create a Service&#34;&gt;&lt;/a&gt;Create a Service&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# scaffold a project&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat new helloworld&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; helloworld&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# add a proto definition&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto add api/helloworld/helloworld.proto&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# generate client and server code&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto client api/helloworld/helloworld.proto&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto server api/helloworld/helloworld.proto -t internal/service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# run in dev mode&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat run&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;Visit &lt;code&gt;http://localhost:8000/helloworld/ecat&lt;/code&gt;.&lt;/p&gt;
&lt;h3 id=&#34;Code-Example&#34;&gt;&lt;a href=&#34;#Code-Example&#34; class=&#34;headerlink&#34; title=&#34;Code Example&#34;&gt;&lt;/a&gt;Code Example&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat::App;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_transport_http::HttpServer;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_transport_grpc::GrpcServer;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;#[tokio::main]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;() &lt;span class=&#34;punctuation&#34;&gt;-&amp;gt;&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;Result&lt;/span&gt;&amp;lt;(), &lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;dyn&lt;/span&gt; std::error::Error + &lt;span class=&#34;built_in&#34;&gt;Send&lt;/span&gt; + &lt;span class=&#34;built_in&#34;&gt;Sync&lt;/span&gt;&amp;gt;&amp;gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;http_srv&lt;/span&gt; = HttpServer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;:8000&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;grpc_srv&lt;/span&gt; = GrpcServer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;:9000&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;app&lt;/span&gt; = App::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;name&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;my-service&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;version&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;v1.0.0&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;server&lt;/span&gt;(http_srv)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;server&lt;/span&gt;(grpc_srv)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;on_start&lt;/span&gt;(|| &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            tracing::info!(&lt;span class=&#34;string&#34;&gt;&amp;quot;service started&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;on_stop&lt;/span&gt;(|| &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            tracing::info!(&lt;span class=&#34;string&#34;&gt;&amp;quot;service stopped&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;()?;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    app.&lt;span class=&#34;title function_ invoke__&#34;&gt;run&lt;/span&gt;().&lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt;?; &lt;span class=&#34;comment&#34;&gt;// blocks until SIGTERM/SIGINT&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Middleware&#34;&gt;&lt;a href=&#34;#Middleware&#34; class=&#34;headerlink&#34; title=&#34;Middleware&#34;&gt;&lt;/a&gt;Middleware&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; tower::ServiceBuilder;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_middleware::&amp;#123;RecoveryLayer, TracingLayer, LoggingLayer, TimeoutLayer&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; std::time::Duration;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;layer&lt;/span&gt; = ServiceBuilder::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(RecoveryLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(TracingLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(LoggingLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(TimeoutLayer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(Duration::&lt;span class=&#34;title function_ invoke__&#34;&gt;from_secs&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;)))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(SecurityLayer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;());&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Error-Handling&#34;&gt;&lt;a href=&#34;#Error-Handling&#34; class=&#34;headerlink&#34; title=&#34;Error Handling&#34;&gt;&lt;/a&gt;Error Handling&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_errors::&amp;#123;Error, ErrorCode&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;get_user&lt;/span&gt;(id: &lt;span class=&#34;type&#34;&gt;u64&lt;/span&gt;) &lt;span class=&#34;punctuation&#34;&gt;-&amp;gt;&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;Result&lt;/span&gt;&amp;lt;User, Error&amp;gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; id == &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;title function_ invoke__&#34;&gt;Err&lt;/span&gt;(Error::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            ErrorCode::InvalidArgument,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;quot;bad_request&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;quot;user id must be positive&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ));&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;Implementation-Phases&#34;&gt;&lt;a href=&#34;#Implementation-Phases&#34; class=&#34;headerlink&#34; title=&#34;Implementation Phases&#34;&gt;&lt;/a&gt;Implementation Phases&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Phase&lt;/th&gt;
&lt;th&gt;Status&lt;/th&gt;
&lt;th&gt;Content&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Phase 1&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Project skeleton, protos, errors, metadata, encoding, logging&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 2&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Transport layer (HTTP + gRPC)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 3&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Middleware system (Recovery/Tracing/Logging/Timeout)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 4&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;App lifecycle management&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 5&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Registry, Config, Metrics&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 5.5&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Data access layer (traits + sqlx backends)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 6&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;CLI toolchain (new/proto/run/build)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 7&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;README, examples (helloworld), design docs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 8&lt;/td&gt;
&lt;td&gt;✅ Done&lt;/td&gt;
&lt;td&gt;Attack detection integration (security-rust, ecat-security)&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Design-Goals&#34;&gt;&lt;a href=&#34;#Design-Goals&#34; class=&#34;headerlink&#34; title=&#34;Design Goals&#34;&gt;&lt;/a&gt;Design Goals&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;#&lt;/th&gt;
&lt;th&gt;Goal&lt;/th&gt;
&lt;th&gt;Notes&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Kratos alignment&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Keep Kratos’s API-first, pluggable, unified-abstraction philosophy&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Idiomatic Rust&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Reuse tower::Service, trait generics, and zero-cost abstractions; no “Go in Rust”&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Type safety&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Catch errors at compile time; every Protobuf definition is strongly typed&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Pluggable&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Registry, Config, Logging, and Encoding are all abstracted behind traits&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Complete toolchain&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;The CLI covers project scaffolding, proto code generation, and dev runs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Performance first&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Zero-cost abstractions + async runtime&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Observable&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;tracing + OpenTelemetry + Prometheus out of the box&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Technical-Notes&#34;&gt;&lt;a href=&#34;#Technical-Notes&#34; class=&#34;headerlink&#34; title=&#34;Technical Notes&#34;&gt;&lt;/a&gt;Technical Notes&lt;/h2&gt;&lt;h3 id=&#34;Why-tower-Service&#34;&gt;&lt;a href=&#34;#Why-tower-Service&#34; class=&#34;headerlink&#34; title=&#34;Why tower::Service&#34;&gt;&lt;/a&gt;Why tower::Service&lt;/h3&gt;&lt;p&gt;&lt;a href=&#34;https://docs.rs/tower/latest/tower/trait.Service.html&#34;&gt;&lt;code&gt;tower::Service&lt;/code&gt;&lt;/a&gt; is the Rust async ecosystem’s equivalent of &lt;code&gt;http.Handler&lt;/code&gt;. Both axum and tonic are built on tower, so e-cat needs no custom middleware trait — shipping tower::Layer implementations directly gives you the same effect as Kratos middleware, with zero adapter overhead.&lt;/p&gt;
&lt;h3 id=&#34;Why-a-Cargo-Workspace&#34;&gt;&lt;a href=&#34;#Why-a-Cargo-Workspace&#34; class=&#34;headerlink&#34; title=&#34;Why a Cargo Workspace&#34;&gt;&lt;/a&gt;Why a Cargo Workspace&lt;/h3&gt;&lt;p&gt;It matches Kratos’s modular design. Every &lt;code&gt;ecat-*&lt;/code&gt; crate is versioned and compiled independently, and users pull in only what they need. Core crates keep their dependencies minimal, while contrib crates provide optional integrations.&lt;/p&gt;
&lt;h3 id=&#34;Why-prost-and-not-protobuf-rs&#34;&gt;&lt;a href=&#34;#Why-prost-and-not-protobuf-rs&#34; class=&#34;headerlink&#34; title=&#34;Why prost (and not protobuf-rs)&#34;&gt;&lt;/a&gt;Why prost (and not protobuf-rs)&lt;/h3&gt;&lt;p&gt;prost is the most widely used protobuf implementation in the Rust community; it generates type-safe code at compile time and integrates deeply with tonic.&lt;/p&gt;
&lt;h2 id=&#34;Design-Docs&#34;&gt;&lt;a href=&#34;#Design-Docs&#34; class=&#34;headerlink&#34; title=&#34;Design Docs&#34;&gt;&lt;/a&gt;Design Docs&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/e-cat/blob/main/docs/superpowers/specs/2026-07-29-ecat-framework-design.md&#34;&gt;Design specification&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/e-cat/blob/main/docs/superpowers/plans/2026-07-29-ecat-framework.md&#34;&gt;Implementation plan&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;License&#34;&gt;&lt;a href=&#34;#License&#34; class=&#34;headerlink&#34; title=&#34;License&#34;&gt;&lt;/a&gt;License&lt;/h2&gt;&lt;p&gt;MIT&lt;/p&gt;

 &lt;!-- Copyright (c) 2026 erik &lt;erik@erik.xyz&gt; — https://erik.xyz --&gt;
&lt;h1 id=&#34;Ecat&#34;&gt;&lt;a href=&#34;#Ecat&#34; class=&#34;headerlink&#34; title=&#34;Ecat&#34;&gt;&lt;/a&gt;Ecat&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/e-cat/blob/main/README.en.md&#34;&gt;English&lt;/a&gt; | 简体中文&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;e-cat&lt;/strong&gt; 是对标 &lt;a href=&#34;https://github.com/go-kratos/kratos&#34;&gt;go-kratos/kratos&lt;/a&gt; v3 的 Rust 微服务框架。&lt;/p&gt;
&lt;p&gt;提供 API-first 开发体验、可插拔的组件架构、统一的 HTTP/gRPC 中间件抽象，以及完备的 CLI 工具链。让熟悉 Kratos 的开发者可以无缝上手，同时充分利用 Rust 的类型安全、零成本抽象和极致性能。&lt;/p&gt;
&lt;h2 id=&#34;设计架构&#34;&gt;&lt;a href=&#34;#设计架构&#34; class=&#34;headerlink&#34; title=&#34;设计架构&#34;&gt;&lt;/a&gt;设计架构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────────────────────────────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                         ecat-cli                             │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│              (new │ proto │ run │ build)                     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├──────────────────────────────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                     ecat (应用生命周期)                         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│      AppBuilder → App &amp;#123; name, servers, hooks, ... &amp;#125;         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├────────────────────┬────────────────────┬────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     transport      │    middleware      │     registry       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     ─────────      │    ──────────      │     ────────       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     HTTP (axum)    │    RecoveryLayer   │     memory         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     gRPC (tonic)   │    TracingLayer    │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     encoding       │    LoggingLayer    │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                    │    TimeoutLayer    │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                    │    SecurityLayer   │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├────────────────────┼────────────────────┼────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     config         │     errors         │     metadata       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     ──────         │     ──────         │     ────────       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     file / env     │     ErrorCode      │     key-value      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     remote source  │     Error          │     HTTP/gRPC      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├────────────────────┴────────────────────┴────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                         data 层                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     ────────────────────────────────────────────────          │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     rdbms:   SQLite / PostgreSQL / MySQL / TiDB              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     cache:   Redis / Memcached                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     olap:    ClickHouse                                      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     search:  OpenSearch / Elasticsearch                      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     graph:   Neo4j / NebulaGraph / ArangoDB                  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     tsdb:    InfluxDB / Apache IoTDB / QuestDB               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├──────────────────────────────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                       ecat-protos                             │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     (共享 .proto 定义: errors, metadata, ...)                 │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────────────────────────────────────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h3 id=&#34;请求处理流程&#34;&gt;&lt;a href=&#34;#请求处理流程&#34; class=&#34;headerlink&#34; title=&#34;请求处理流程&#34;&gt;&lt;/a&gt;请求处理流程&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;客户端请求&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ├─ HTTP :8000 ────→ axum::Router ──┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │                                   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  └─ gRPC :9000 ────→ tonic::Server ─┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              ┌───────┴───────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │   Middleware   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │   ──────────   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ 1. Recovery    │  捕获 panic&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ 2. Tracing     │  注入 trace_id&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ 3. Logging     │  请求日志&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ 4. Auth        │  认证鉴权&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ 5. Metrics     │  指标采集&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ 6. Security    │  攻击检测（仅告警）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              └───────┬───────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              ┌───────┴───────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │    Handler     │  用户业务逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ (tower::Service)│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              └───────┬───────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              ┌───────┴───────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │   Response     │  编码序列化&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              │ JSON/Protobuf  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                              └───────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;功能&#34;&gt;&lt;a href=&#34;#功能&#34; class=&#34;headerlink&#34; title=&#34;功能&#34;&gt;&lt;/a&gt;功能&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;API-first&lt;/strong&gt;：Protobuf 定义 API、错误码、元数据；prost + tonic-build 代码生成&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;双协议支持&lt;/strong&gt;：HTTP（axum）和 gRPC（tonic）共用同一套 tower::Layer 中间件&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;可插拔架构&lt;/strong&gt;：Registry、Config、Logging、Encoding 全部通过 trait 抽象，默认提供生产可用实现&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;中间件体系&lt;/strong&gt;：内置 Recovery、Tracing、Logging、Timeout、Security；通过 tower::ServiceBuilder 组合&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;应用生命周期&lt;/strong&gt;：Builder 模式构建 App，多 Server 并发启动，SIGTERM/SIGINT 信号处理，start/stop 生命周期钩子&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;类型安全&lt;/strong&gt;：基于 protobuf 的错误码体系，编译期 HTTP 状态码映射&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;可观测性&lt;/strong&gt;：tracing + opentelemetry + Prometheus 开箱即用&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;攻击检测&lt;/strong&gt;：27 种攻击模式自动识别（SQL 注入、XSS、SSRF、路径遍历等），仅日志告警不阻断&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;多数据源&lt;/strong&gt;：RDBMS（SQLite/PG/MySQL/TiDB）、缓存、OLAP、搜索引擎、图数据库、时序数据库&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Kratos-概念映射&#34;&gt;&lt;a href=&#34;#Kratos-概念映射&#34; class=&#34;headerlink&#34; title=&#34;Kratos 概念映射&#34;&gt;&lt;/a&gt;Kratos 概念映射&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Kratos (Go)&lt;/th&gt;
&lt;th&gt;e-cat (Rust)&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;kratos.New()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;App::builder()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Builder 模式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;http.Handler&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;tower::Service&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Rust 生态标准 trait&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;http.Server&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;axum::Router&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;社区主流 HTTP 框架&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;grpc.Server&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;tonic::transport::Server&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;最成熟的 gRPC 实现&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;proto generate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;prost + tonic-build&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;社区标准 protobuf&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;registry.Discovery&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Registry&lt;/code&gt; trait&lt;/td&gt;
&lt;td&gt;可插拔注册发现&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;config.Source&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ConfigSource&lt;/code&gt; trait&lt;/td&gt;
&lt;td&gt;多源配置加载&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;技术栈&#34;&gt;&lt;a href=&#34;#技术栈&#34; class=&#34;headerlink&#34; title=&#34;技术栈&#34;&gt;&lt;/a&gt;技术栈&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;组件&lt;/th&gt;
&lt;th&gt;选型&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;异步运行时&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;tokio&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;HTTP&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;axum&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;gRPC&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;tonic&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Protobuf&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;prost + tonic-build&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;中间件&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;tower::Service / Layer&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;日志/追踪&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;tracing + opentelemetry-rust&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;指标&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;prometheus&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;序列化&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;serde + prost&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;攻击检测&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;security-rust&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;sqlx&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;CLI&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;clap&lt;/strong&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;支持的数据库&#34;&gt;&lt;a href=&#34;#支持的数据库&#34; class=&#34;headerlink&#34; title=&#34;支持的数据库&#34;&gt;&lt;/a&gt;支持的数据库&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;类别&lt;/th&gt;
&lt;th&gt;数据库&lt;/th&gt;
&lt;th&gt;Crate&lt;/th&gt;
&lt;th&gt;Rust 驱动&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;SQLite&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;PostgreSQL&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;MySQL&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;RDBMS&lt;/td&gt;
&lt;td&gt;TiDB&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ecat-data-sqlx&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;a href=&#34;https://crates.io/crates/sqlx&#34;&gt;sqlx&lt;/a&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;缓存&lt;/td&gt;
