&lt;blockquote&gt;
&lt;p&gt;所有数据后端通过统一的 trait 抽象（&lt;code&gt;RdbmsClient&lt;/code&gt; / &lt;code&gt;Cache&lt;/code&gt; / &lt;code&gt;SearchClient&lt;/code&gt; / &lt;code&gt;GraphClient&lt;/code&gt; / &lt;code&gt;TsdbClient&lt;/code&gt;），按需引入对应 contrib crate。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;项目结构&#34;&gt;&lt;a href=&#34;#项目结构&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;e-cat/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat/                       # 核心：App 生命周期&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport/             # 传输抽象（Server trait）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport-http/        # axum 实现&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-transport-grpc/        # tonic 实现&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-middleware/            # tower::Layer 中间件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-protos/                # Protobuf 定义&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-errors/                # 错误码体系&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-metadata/              # 元数据传递&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-encoding/              # 序列化抽象&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-logging/               # tracing 集成&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-registry/              # 服务注册发现&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-config/                # 配置管理&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-metrics/               # Prometheus 集成&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-data/                  # 数据访问 trait&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-security/              # 攻击检测（security-rust）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ecat-cli/                   # CLI 工具&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                       # 设计文档与实现计划&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── examples/                   # 示例项目&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h2&gt;&lt;h3 id=&#34;前提条件&#34;&gt;&lt;a href=&#34;#前提条件&#34; class=&#34;headerlink&#34; title=&#34;前提条件&#34;&gt;&lt;/a&gt;前提条件&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;Rust 1.80+（stable 工具链）&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/protocolbuffers/protobuf&#34;&gt;protoc&lt;/a&gt;（Protocol Buffers 编译器）&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;安装-CLI&#34;&gt;&lt;a href=&#34;#安装-CLI&#34; class=&#34;headerlink&#34; title=&#34;安装 CLI&#34;&gt;&lt;/a&gt;安装 CLI&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;cargo install ecat-cli&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;创建服务&#34;&gt;&lt;a href=&#34;#创建服务&#34; class=&#34;headerlink&#34; title=&#34;创建服务&#34;&gt;&lt;/a&gt;创建服务&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 脚手架生成项目&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat new helloworld&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; helloworld&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 添加 proto 定义&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto add api/helloworld/helloworld.proto&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 生成客户端和服务端代码&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto client api/helloworld/helloworld.proto&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat proto server api/helloworld/helloworld.proto -t internal/service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 开发模式运行&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;ecat run&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;访问 &lt;code&gt;http://localhost:8000/helloworld/ecat&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;代码示例&#34;&gt;&lt;a href=&#34;#代码示例&#34; class=&#34;headerlink&#34; title=&#34;代码示例&#34;&gt;&lt;/a&gt;代码示例&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat::App;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_transport_http::HttpServer;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_transport_grpc::GrpcServer;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;#[tokio::main]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;() &lt;span class=&#34;punctuation&#34;&gt;-&amp;gt;&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;Result&lt;/span&gt;&amp;lt;(), &lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;&amp;lt;&lt;span class=&#34;keyword&#34;&gt;dyn&lt;/span&gt; std::error::Error + &lt;span class=&#34;built_in&#34;&gt;Send&lt;/span&gt; + &lt;span class=&#34;built_in&#34;&gt;Sync&lt;/span&gt;&amp;gt;&amp;gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;http_srv&lt;/span&gt; = HttpServer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;:8000&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;grpc_srv&lt;/span&gt; = GrpcServer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;:9000&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;app&lt;/span&gt; = App::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;name&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;my-service&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;version&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;v1.0.0&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;server&lt;/span&gt;(http_srv)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;server&lt;/span&gt;(grpc_srv)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;on_start&lt;/span&gt;(|| &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            tracing::info!(&lt;span class=&#34;string&#34;&gt;&amp;quot;service started&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;on_stop&lt;/span&gt;(|| &lt;span class=&#34;keyword&#34;&gt;async&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            tracing::info!(&lt;span class=&#34;string&#34;&gt;&amp;quot;service stopped&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;()?;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    app.&lt;span class=&#34;title function_ invoke__&#34;&gt;run&lt;/span&gt;().&lt;span class=&#34;keyword&#34;&gt;await&lt;/span&gt;?; &lt;span class=&#34;comment&#34;&gt;// 阻塞直到 SIGTERM/SIGINT&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;title function_ invoke__&#34;&gt;Ok&lt;/span&gt;(())&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;中间件&#34;&gt;&lt;a href=&#34;#中间件&#34; class=&#34;headerlink&#34; title=&#34;中间件&#34;&gt;&lt;/a&gt;中间件&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; tower::ServiceBuilder;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_middleware::&amp;#123;RecoveryLayer, TracingLayer, LoggingLayer, TimeoutLayer&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; std::time::Duration;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;layer&lt;/span&gt; = ServiceBuilder::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(RecoveryLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(TracingLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(LoggingLayer)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(TimeoutLayer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(Duration::&lt;span class=&#34;title function_ invoke__&#34;&gt;from_secs&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;)))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;layer&lt;/span&gt;(SecurityLayer::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;());&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;错误处理&#34;&gt;&lt;a href=&#34;#错误处理&#34; class=&#34;headerlink&#34; title=&#34;错误处理&#34;&gt;&lt;/a&gt;错误处理&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; ecat_errors::&amp;#123;Error, ErrorCode&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;get_user&lt;/span&gt;(id: &lt;span class=&#34;type&#34;&gt;u64&lt;/span&gt;) &lt;span class=&#34;punctuation&#34;&gt;-&amp;gt;&lt;/span&gt; &lt;span class=&#34;type&#34;&gt;Result&lt;/span&gt;&amp;lt;User, Error&amp;gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; id == &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;title function_ invoke__&#34;&gt;Err&lt;/span&gt;(Error::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            ErrorCode::InvalidArgument,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;quot;bad_request&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;quot;user id must be positive&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ));&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;实现阶段&#34;&gt;&lt;a href=&#34;#实现阶段&#34; class=&#34;headerlink&#34; title=&#34;实现阶段&#34;&gt;&lt;/a&gt;实现阶段&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;阶段&lt;/th&gt;
&lt;th&gt;状态&lt;/th&gt;
&lt;th&gt;内容&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Phase 1&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;项目骨架、protos、errors、metadata、encoding、logging&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 2&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;Transport 层（HTTP + gRPC）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 3&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;Middleware 体系（Recovery/Tracing/Logging/Timeout）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 4&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;App 生命周期管理&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 5&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;Registry、Config、Metrics&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 5.5&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;Data 访问层（traits + sqlx 后端）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 6&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;CLI 工具链（new/proto/run/build）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 7&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;README、示例（helloworld）、设计文档&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Phase 8&lt;/td&gt;
&lt;td&gt;✅ 完成&lt;/td&gt;
&lt;td&gt;攻击检测集成（security-rust, ecat-security）&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;设计目标&#34;&gt;&lt;a href=&#34;#设计目标&#34; class=&#34;headerlink&#34; title=&#34;设计目标&#34;&gt;&lt;/a&gt;设计目标&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;#&lt;/th&gt;
&lt;th&gt;目标&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Kratos 对齐&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;保持 Kratos 的 API-first、可插拔、统一抽象理念&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Rust 惯用&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;复用 tower::Service、trait 泛型、零成本抽象；不做「Go in Rust」&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;类型安全&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;编译期捕获错误，Protobuf 定义全强类型化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;可插拔&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Registry、Config、Logging、Encoding 全部通过 trait 抽象&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;工具链完备&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CLI 支持项目脚手架、proto 代码生成、开发运行&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;性能优先&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;零成本抽象 + 异步运行时&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;可观测&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;tracing + OpenTelemetry + Prometheus 开箱即用&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;技术说明&#34;&gt;&lt;a href=&#34;#技术说明&#34; class=&#34;headerlink&#34; title=&#34;技术说明&#34;&gt;&lt;/a&gt;技术说明&lt;/h2&gt;&lt;h3 id=&#34;为什么选择-tower-Service&#34;&gt;&lt;a href=&#34;#为什么选择-tower-Service&#34; class=&#34;headerlink&#34; title=&#34;为什么选择 tower::Service&#34;&gt;&lt;/a&gt;为什么选择 tower::Service&lt;/h3&gt;&lt;p&gt;&lt;a href=&#34;https://docs.rs/tower/latest/tower/trait.Service.html&#34;&gt;&lt;code&gt;tower::Service&lt;/code&gt;&lt;/a&gt; 是 Rust 异步生态的 &lt;code&gt;http.Handler&lt;/code&gt; 等价物。axum 和 tonic 都构建在 tower 之上，因此 e-cat 不需要自定义中间件 trait——直接提供 tower::Layer 实现即可达到与 Kratos 中间件相同的效果，且零适配器开销。&lt;/p&gt;
&lt;h3 id=&#34;为什么用-Cargo-Workspace&#34;&gt;&lt;a href=&#34;#为什么用-Cargo-Workspace&#34; class=&#34;headerlink&#34; title=&#34;为什么用 Cargo Workspace&#34;&gt;&lt;/a&gt;为什么用 Cargo Workspace&lt;/h3&gt;&lt;p&gt;与 Kratos 的模块化设计一致。每个 &lt;code&gt;ecat-*&lt;/code&gt; crate 独立版本、独立编译，用户按需引入。核心 crate 保持最小依赖，contrib crate 提供可选集成。&lt;/p&gt;
&lt;h3 id=&#34;为什么用-prost（而非-protobuf-rs）&#34;&gt;&lt;a href=&#34;#为什么用-prost（而非-protobuf-rs）&#34; class=&#34;headerlink&#34; title=&#34;为什么用 prost（而非 protobuf-rs）&#34;&gt;&lt;/a&gt;为什么用 prost（而非 protobuf-rs）&lt;/h3&gt;&lt;p&gt;prost 是 Rust 社区最广泛使用的 protobuf 实现，编译期生成类型安全代码，与 tonic 深度集成。&lt;/p&gt;
&lt;h2 id=&#34;设计文档&#34;&gt;&lt;a href=&#34;#设计文档&#34; class=&#34;headerlink&#34; title=&#34;设计文档&#34;&gt;&lt;/a&gt;设计文档&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/e-cat/blob/main/docs/superpowers/specs/2026-07-29-ecat-framework-design.md&#34;&gt;设计规范&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/e-cat/blob/main/docs/superpowers/plans/2026-07-29-ecat-framework.md&#34;&gt;实现计划&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;许可证&#34;&gt;&lt;a href=&#34;#许可证&#34; class=&#34;headerlink&#34; title=&#34;许可证&#34;&gt;&lt;/a&gt;许可证&lt;/h2&gt;&lt;p&gt;MIT&lt;/p&gt;

 &lt;h1 id=&#34;Coding-to-Rust-—-a-skill-collection-for-migrating-to-Rust-from-many-languages&#34;&gt;&lt;a href=&#34;#Coding-to-Rust-—-a-skill-collection-for-migrating-to-Rust-from-many-languages&#34; class=&#34;headerlink&#34; title=&#34;Coding to Rust — a skill collection for migrating to Rust from many languages&#34;&gt;&lt;/a&gt;Coding to Rust — a skill collection for migrating to Rust from many languages&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/coding-to-rust/blob/main/README.en.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;Project-overview&#34;&gt;&lt;a href=&#34;#Project-overview&#34; class=&#34;headerlink&#34; title=&#34;Project overview&#34;&gt;&lt;/a&gt;Project overview&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;&lt;a href=&#34;https://github.com/erikwang2013/coding-to-rust&#34;&gt;Coding to Rust&lt;/a&gt;&lt;/strong&gt; is a Claude Code skill collection that provides a complete guide for migrating from 16 mainstream programming languages to Rust. For each language it offers:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Architecture mapping&lt;/strong&gt; — runtime differences, paradigm shifts, memory model comparisons&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Type system mapping tables&lt;/strong&gt; — 30-80 precise type/syntax mappings&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Framework migration guides&lt;/strong&gt; — how mainstream frameworks map to the Rust ecosystem (such as Django→Axum, Spring→Actix)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Idiom comparisons&lt;/strong&gt; — before/after comparisons with code examples&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Common mistakes&lt;/strong&gt; — the mistakes developers from that language make most often in Rust, and how to fix them&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Incremental FFI migration strategy&lt;/strong&gt; — a phased replacement plan&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Reference implementations&lt;/strong&gt; — real-world migration cases and projects&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h2 id=&#34;Covered-languages&#34;&gt;&lt;a href=&#34;#Covered-languages&#34; class=&#34;headerlink&#34; title=&#34;Covered languages&#34;&gt;&lt;/a&gt;Covered languages&lt;/h2&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;#&lt;/th&gt;
&lt;th&gt;Language&lt;/th&gt;
&lt;th&gt;Directory&lt;/th&gt;
&lt;th&gt;Core paradigm shift&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;Python&lt;/td&gt;
&lt;td&gt;&lt;code&gt;python-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;GIL→true parallelism, asyncio→tokio, numpy/pandas→ndarray/polars&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;JavaScript/TypeScript&lt;/td&gt;
&lt;td&gt;&lt;code&gt;nodejs-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;event loop→tokio, V8→AOT, Express→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;Go&lt;/td&gt;
&lt;td&gt;&lt;code&gt;go-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;goroutine→tokio task, channel→mpsc, GC→ownership&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;Java&lt;/td&gt;
&lt;td&gt;&lt;code&gt;java-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JVM→native binary, Spring→Axum, JPA→sqlx&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;C#&lt;/td&gt;
&lt;td&gt;&lt;code&gt;csharp-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CLR→native, LINQ→iterators, ASP.NET→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6&lt;/td&gt;
&lt;td&gt;PHP&lt;/td&gt;
&lt;td&gt;&lt;code&gt;php-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;dynamic types→static types, FPM→long-running process, Laravel→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7&lt;/td&gt;
&lt;td&gt;C&lt;/td&gt;
&lt;td&gt;&lt;code&gt;c-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;malloc/free→ownership, pointers→references, header files→modules&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;8&lt;/td&gt;
&lt;td&gt;C++&lt;/td&gt;
&lt;td&gt;&lt;code&gt;cpp-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;templates→generics, virtual functions→traits, move semantics→ownership&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;Zig&lt;/td&gt;
&lt;td&gt;&lt;code&gt;zig-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;comptime→macros, allocators→ownership, error sets→Result&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;10&lt;/td&gt;
&lt;td&gt;Lua&lt;/td&gt;
&lt;td&gt;&lt;code&gt;lua-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;table→struct/enum, metatable OOP→traits, coroutine→async&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;11&lt;/td&gt;
&lt;td&gt;R&lt;/td&gt;
&lt;td&gt;&lt;code&gt;r-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;data.frame→polars, formula→builder, apply→iterators&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;12&lt;/td&gt;
&lt;td&gt;Julia&lt;/td&gt;
&lt;td&gt;&lt;code&gt;julia-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;multiple dispatch→traits, JIT→AOT, Array→ndarray&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;13&lt;/td&gt;
&lt;td&gt;Kotlin&lt;/td&gt;
&lt;td&gt;&lt;code&gt;kotlin-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Coroutines→tokio, data class→struct, sealed class→enum, Gradle→Cargo&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;14&lt;/td&gt;
&lt;td&gt;Swift&lt;/td&gt;
&lt;td&gt;&lt;code&gt;swift-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;ARC→ownership, actor→Mutex, protocol→trait, SwiftUI→Leptos&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;15&lt;/td&gt;
&lt;td&gt;Ruby&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ruby-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;GC→ownership, blocks→closures, Rails→Axum, Bundler→Cargo&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;16&lt;/td&gt;
&lt;td&gt;Vue&lt;/td&gt;
&lt;td&gt;&lt;code&gt;vue-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;:warning: &lt;strong&gt;(frontend/WebAssembly — not backend)&lt;/strong&gt; SFC→component functions, ref()→RwSignal, Vite→Trunk&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Project-structure&#34;&gt;&lt;a href=&#34;#Project-structure&#34; class=&#34;headerlink&#34; title=&#34;Project structure&#34;&gt;&lt;/a&gt;Project structure&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;coding-to-rust/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── README.md                 # this file — project documentation (Chinese)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── README.en.md              # English version of the documentation&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── SKILL.md                  # main entry point (Claude Code loads this file)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - quick selector for the 16 languages&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - general migration concepts (ownership/async/error handling/build systems)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 6-8 core quick-mapping entries per language&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - cross-language common mistakes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - language-agnostic 5-phase migration strategy&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── python-to-rust/           # Python → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── php-to-rust/              # PHP → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── nodejs-to-rust/           # JS/TS → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── csharp-to-rust/           # C# → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── cpp-to-rust/              # C++ → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── zig-to-rust/              # Zig → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── java-to-rust/             # Java → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── r-to-rust/                # R → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── go-to-rust/               # Go → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── julia-to-rust/            # Julia → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── c-to-rust/                # C → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── lua-to-rust/              # Lua → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── kotlin-to-rust/           # Kotlin → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── swift-to-rust/            # Swift → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ruby-to-rust/             # Ruby → Rust detailed guide&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── vue-to-rust/              # Vue → Rust (WASM) detailed guide&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;strong&gt;Design principles:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Index entry point&lt;/strong&gt; — &lt;code&gt;SKILL.md&lt;/code&gt; is the main entry, and Claude Code loads it automatically based on keywords&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Independently readable&lt;/strong&gt; — each language directory’s &lt;code&gt;SKILL.md&lt;/code&gt; can be used on its own, without depending on other files&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Progressive depth&lt;/strong&gt; — quick mapping tables (index layer) → architecture mapping (concept layer) → code examples (hands-on layer) → reference projects (verification layer)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Cross-references&lt;/strong&gt; — languages reference shared patterns across each other (for example, Python’s asyncio and Go’s goroutine both map to tokio)&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Usage&#34;&gt;&lt;a href=&#34;#Usage&#34; class=&#34;headerlink&#34; title=&#34;Usage&#34;&gt;&lt;/a&gt;Usage&lt;/h2&gt;&lt;h3 id=&#34;How-to-trigger-it&#34;&gt;&lt;a href=&#34;#How-to-trigger-it&#34; class=&#34;headerlink&#34; title=&#34;How to trigger it&#34;&gt;&lt;/a&gt;How to trigger it&lt;/h3&gt;&lt;p&gt;In a Claude Code conversation, any of the following will automatically load this skill:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;“Migrate this Python code to Rust”&lt;/li&gt;
&lt;li&gt;“Rewrite this Go service in Rust”&lt;/li&gt;
&lt;li&gt;“How do I implement Java’s Spring Boot in Rust”&lt;/li&gt;
&lt;li&gt;“Port this C++ class hierarchy to Rust”&lt;/li&gt;
&lt;li&gt;“Migrate Node.js Express app to Rust”&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Workflow&#34;&gt;&lt;a href=&#34;#Workflow&#34; class=&#34;headerlink&#34; title=&#34;Workflow&#34;&gt;&lt;/a&gt;Workflow&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;Auto-load&lt;/strong&gt; — Claude Code recognizes the migration request and loads &lt;code&gt;coding-to-rust/SKILL.md&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Quick mapping&lt;/strong&gt; — look at the 6-8 core mappings for your language to quickly get the rough correspondence&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Deeper lookup&lt;/strong&gt; — when you need code examples or detailed framework comparisons, Claude automatically reads the detailed &lt;code&gt;SKILL.md&lt;/code&gt; for that language&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Cross-reference&lt;/strong&gt; — for patterns shared across languages, it links to the corresponding sections in other languages via cross-references&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;Recommended-migration-order&#34;&gt;&lt;a href=&#34;#Recommended-migration-order&#34; class=&#34;headerlink&#34; title=&#34;Recommended migration order&#34;&gt;&lt;/a&gt;Recommended migration order&lt;/h3&gt;&lt;p&gt;Whichever source language you start from, it’s best to migrate in this order:&lt;/p&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Phase&lt;/th&gt;
&lt;th&gt;Content&lt;/th&gt;
&lt;th&gt;Approach&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Data types&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Define the corresponding Rust struct/enum, shared via a JSON/Protobuf schema&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Pure functions&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Migrate stateless logic first — no external dependencies, easiest to test&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;I/O boundaries&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Replace HTTP handlers, database queries, file reads/writes&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Concurrency model&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Convert threads/coroutines/async tasks uniformly into tokio tasks&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;Full cutover&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Remove the source language runtime, keeping only an FFI bridge for a compatibility transition&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;File-size-reference&#34;&gt;&lt;a href=&#34;#File-size-reference&#34; class=&#34;headerlink&#34; title=&#34;File size reference&#34;&gt;&lt;/a&gt;File size reference&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Level&lt;/th&gt;
&lt;th&gt;Corresponding file&lt;/th&gt;
&lt;th&gt;Size&lt;/th&gt;
&lt;th&gt;When to use&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Light&lt;/td&gt;
&lt;td&gt;Index layer quick mapping table&lt;/td&gt;
&lt;td&gt;~8 lines/language&lt;/td&gt;
&lt;td&gt;Quick lookup to confirm basic mappings&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;td&gt;Index layer general concepts&lt;/td&gt;
&lt;td&gt;~60 lines&lt;/td&gt;
&lt;td&gt;Understand Rust’s core paradigms&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Detailed&lt;/td&gt;
&lt;td&gt;Each language’s SKILL.md&lt;/td&gt;
&lt;td&gt;600-1000 lines&lt;/td&gt;
&lt;td&gt;Deep migration, code examples, framework comparisons&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Contributing&#34;&gt;&lt;a href=&#34;#Contributing&#34; class=&#34;headerlink&#34; title=&#34;Contributing&#34;&gt;&lt;/a&gt;Contributing&lt;/h2&gt;&lt;p&gt;To add a language, fix an error, or improve the example code, edit the &lt;code&gt;SKILL.md&lt;/code&gt; file for that language, and update the quick mapping table and links in the &lt;code&gt;coding-to-rust/SKILL.md&lt;/code&gt; index as well.&lt;/p&gt;

 &lt;h1 id=&#34;Coding-to-Rust-—-多语言迁移到-Rust-的技能集合&#34;&gt;&lt;a href=&#34;#Coding-to-Rust-—-多语言迁移到-Rust-的技能集合&#34; class=&#34;headerlink&#34; title=&#34;Coding to Rust — 多语言迁移到 Rust 的技能集合&#34;&gt;&lt;/a&gt;Coding to Rust — 多语言迁移到 Rust 的技能集合&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/coding-to-rust/blob/main/README.en.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;项目介绍&#34;&gt;&lt;a href=&#34;#项目介绍&#34; class=&#34;headerlink&#34; title=&#34;项目介绍&#34;&gt;&lt;/a&gt;项目介绍&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;&lt;a href=&#34;https://github.com/erikwang2013/coding-to-rust&#34;&gt;Coding to Rust&lt;/a&gt;&lt;/strong&gt; 是一个 Claude Code 技能集合，覆盖从 16 种主流编程语言迁移到 Rust 的完整指南。每种语言提供：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;架构映射&lt;/strong&gt; — 运行时差异、范式转换、内存模型对照&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;类型系统对照表&lt;/strong&gt; — 30-80 条精确的类型/语法映射&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;框架迁移指南&lt;/strong&gt; — 主流框架到 Rust 生态的对照（如 Django→Axum、Spring→Actix）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;标准模式对照&lt;/strong&gt; — 带代码示例的 before/after 对比&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;常见错误&lt;/strong&gt; — 该语言开发者在 Rust 中最容易犯的错误及修复方法&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;FFI 渐进迁移策略&lt;/strong&gt; — 分阶段替换方案&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;参考实现&lt;/strong&gt; — 真实世界的迁移案例和项目&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h2 id=&#34;覆盖语言&#34;&gt;&lt;a href=&#34;#覆盖语言&#34; class=&#34;headerlink&#34; title=&#34;覆盖语言&#34;&gt;&lt;/a&gt;覆盖语言&lt;/h2&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;#&lt;/th&gt;
&lt;th&gt;语言&lt;/th&gt;
&lt;th&gt;目录&lt;/th&gt;
&lt;th&gt;核心范式转换&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;Python&lt;/td&gt;
&lt;td&gt;&lt;code&gt;python-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;GIL→真并行、asyncio→tokio、numpy/pandas→ndarray/polars&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;JavaScript/TypeScript&lt;/td&gt;
&lt;td&gt;&lt;code&gt;nodejs-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;事件循环→tokio、V8→AOT、Express→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;Go&lt;/td&gt;
&lt;td&gt;&lt;code&gt;go-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;goroutine→tokio task、channel→mpsc、GC→所有权&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;Java&lt;/td&gt;
&lt;td&gt;&lt;code&gt;java-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JVM→原生二进制、Spring→Axum、JPA→sqlx&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;C#&lt;/td&gt;
&lt;td&gt;&lt;code&gt;csharp-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;CLR→原生、LINQ→迭代器、ASP.NET→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6&lt;/td&gt;
&lt;td&gt;PHP&lt;/td&gt;
&lt;td&gt;&lt;code&gt;php-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;动态类型→静态类型、FPM→长驻进程、Laravel→Axum&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7&lt;/td&gt;
&lt;td&gt;C&lt;/td&gt;
&lt;td&gt;&lt;code&gt;c-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;malloc/free→所有权、指针→引用、头文件→模块&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;8&lt;/td&gt;
&lt;td&gt;C++&lt;/td&gt;
&lt;td&gt;&lt;code&gt;cpp-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;模板→泛型、虚函数→trait、移动语义→所有权&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;Zig&lt;/td&gt;
&lt;td&gt;&lt;code&gt;zig-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;comptime→宏、分配器→所有权、错误集→Result&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;10&lt;/td&gt;
&lt;td&gt;Lua&lt;/td&gt;
&lt;td&gt;&lt;code&gt;lua-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;table→struct/enum、元表OOP→trait、coroutine→async&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;11&lt;/td&gt;
&lt;td&gt;R&lt;/td&gt;
&lt;td&gt;&lt;code&gt;r-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;data.frame→polars、formula→builder、apply→迭代器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;12&lt;/td&gt;
&lt;td&gt;Julia&lt;/td&gt;
&lt;td&gt;&lt;code&gt;julia-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;多重分派→trait、JIT→AOT、Array→ndarray&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;13&lt;/td&gt;
&lt;td&gt;Kotlin&lt;/td&gt;
&lt;td&gt;&lt;code&gt;kotlin-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Coroutines→tokio、data class→struct、sealed class→enum、Gradle→Cargo&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;14&lt;/td&gt;
&lt;td&gt;Swift&lt;/td&gt;
&lt;td&gt;&lt;code&gt;swift-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;ARC→ownership、actor→Mutex、protocol→trait、SwiftUI→Leptos&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;15&lt;/td&gt;
&lt;td&gt;Ruby&lt;/td&gt;
&lt;td&gt;&lt;code&gt;ruby-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;GC→ownership、blocks→closures、Rails→Axum、Bundler→Cargo&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;16&lt;/td&gt;
&lt;td&gt;Vue&lt;/td&gt;
&lt;td&gt;&lt;code&gt;vue-to-rust/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;:warning: &lt;strong&gt;(前端/WebAssembly — 非后端)&lt;/strong&gt; SFC→组件函数、ref()→RwSignal、Vite→Trunk&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;项目架构&#34;&gt;&lt;a href=&#34;#项目架构&#34; class=&#34;headerlink&#34; title=&#34;项目架构&#34;&gt;&lt;/a&gt;项目架构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;coding-to-rust/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── README.md                 # 本文件 — 项目说明（中文）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── README.en.md              # 英文版项目说明&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── SKILL.md                  # 总入口（Claude Code 加载此文件）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 16 语言快速选择器&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 通用迁移概念（所有权/异步/错误处理/构建系统）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 各语言 6-8 条核心快速对照表&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 跨语言通用错误&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                               - 语言无关的 5 阶段迁移策略&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── python-to-rust/           # Python → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── php-to-rust/              # PHP → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── nodejs-to-rust/           # JS/TS → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── csharp-to-rust/           # C# → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── cpp-to-rust/              # C++ → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── zig-to-rust/              # Zig → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── java-to-rust/             # Java → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── r-to-rust/                # R → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── go-to-rust/               # Go → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── julia-to-rust/            # Julia → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── c-to-rust/                # C → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── lua-to-rust/              # Lua → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── kotlin-to-rust/           # Kotlin → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── swift-to-rust/            # Swift → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── ruby-to-rust/             # Ruby → Rust 详细指南&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── vue-to-rust/              # Vue → Rust (WASM) 详细指南&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;strong&gt;设计原则：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;索引入口&lt;/strong&gt; — &lt;code&gt;SKILL.md&lt;/code&gt; 作为总入口，Claude Code 根据关键词自动加载&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;独立可读&lt;/strong&gt; — 每个语言目录的 &lt;code&gt;SKILL.md&lt;/code&gt; 可独立使用，不依赖其他文件&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;渐进深度&lt;/strong&gt; — 快速对照表（索引层）→ 架构映射（概念层）→ 代码示例（实操层）→ 参考项目（验证层）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;交叉引用&lt;/strong&gt; — 各语言互相引用共享模式（如 Python 的 asyncio 和 Go 的 goroutine 都映射到 tokio）&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;使用说明&#34;&gt;&lt;a href=&#34;#使用说明&#34; class=&#34;headerlink&#34; title=&#34;使用说明&#34;&gt;&lt;/a&gt;使用说明&lt;/h2&gt;&lt;h3 id=&#34;触发方式&#34;&gt;&lt;a href=&#34;#触发方式&#34; class=&#34;headerlink&#34; title=&#34;触发方式&#34;&gt;&lt;/a&gt;触发方式&lt;/h3&gt;&lt;p&gt;在 Claude Code 对话中，以下任何一种说法都会自动加载此技能：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;「把这段 Python 代码迁移到 Rust」&lt;/li&gt;
&lt;li&gt;「用 Rust 重写这个 Go 服务」&lt;/li&gt;
&lt;li&gt;「Java 的 Spring Boot 怎么用 Rust 实现」&lt;/li&gt;
&lt;li&gt;「Port this C++ class hierarchy to Rust」&lt;/li&gt;
&lt;li&gt;「Migrate Node.js Express app to Rust」&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;使用流程&#34;&gt;&lt;a href=&#34;#使用流程&#34; class=&#34;headerlink&#34; title=&#34;使用流程&#34;&gt;&lt;/a&gt;使用流程&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;自动加载&lt;/strong&gt; — Claude Code 识别到迁移需求，加载 &lt;code&gt;coding-to-rust/SKILL.md&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;快速对照&lt;/strong&gt; — 查看你所用语言的 6-8 条核心映射，快速理解大致对应关系&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;深入查阅&lt;/strong&gt; — 需要代码示例、框架详细对照时，Claude 自动读取对应语言的详细 &lt;code&gt;SKILL.md&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;交叉参考&lt;/strong&gt; — 涉及多语言共享模式时，通过交叉引用链接到其他语言的对应章节&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;推荐的迁移顺序&#34;&gt;&lt;a href=&#34;#推荐的迁移顺序&#34; class=&#34;headerlink&#34; title=&#34;推荐的迁移顺序&#34;&gt;&lt;/a&gt;推荐的迁移顺序&lt;/h3&gt;&lt;p&gt;无论哪种源语言，建议按以下顺序执行迁移：&lt;/p&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;阶段&lt;/th&gt;
&lt;th&gt;内容&lt;/th&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;数据类型&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;定义对应的 Rust struct/enum，通过 JSON/Protobuf schema 共享&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;纯函数&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;先迁移无状态逻辑，无外部依赖，最容易编写测试&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;I/O 边界&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;替换 HTTP handler、数据库查询、文件读写&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;并发模型&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;将线程/协程/异步任务统一转换为 tokio task&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;完全切换&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;移除源语言运行时，仅保留 FFI 桥接做兼容过渡&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;文件大小参考&#34;&gt;&lt;a href=&#34;#文件大小参考&#34; class=&#34;headerlink&#34; title=&#34;文件大小参考&#34;&gt;&lt;/a&gt;文件大小参考&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;层级&lt;/th&gt;
&lt;th&gt;对应文件&lt;/th&gt;
&lt;th&gt;规模&lt;/th&gt;
&lt;th&gt;适用场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;轻量&lt;/td&gt;
&lt;td&gt;索引层快速对照表&lt;/td&gt;
&lt;td&gt;~8 行/语言&lt;/td&gt;
&lt;td&gt;快速查询，确认基本映射&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;中等&lt;/td&gt;
&lt;td&gt;索引层通用概念&lt;/td&gt;
&lt;td&gt;~60 行&lt;/td&gt;
&lt;td&gt;理解 Rust 核心范式&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;详细&lt;/td&gt;
&lt;td&gt;各语言 SKILL.md&lt;/td&gt;
&lt;td&gt;600-1000 行&lt;/td&gt;
&lt;td&gt;深度迁移、代码示例、框架对照&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;贡献&#34;&gt;&lt;a href=&#34;#贡献&#34; class=&#34;headerlink&#34; title=&#34;贡献&#34;&gt;&lt;/a&gt;贡献&lt;/h2&gt;&lt;p&gt;如需新增语言、修复错误或改进示例代码，请编辑对应语言的 &lt;code&gt;SKILL.md&lt;/code&gt; 文件，并同步更新 &lt;code&gt;coding-to-rust/SKILL.md&lt;/code&gt; 索引中的快速对照表和链接。&lt;/p&gt;

 &lt;!-- Copyright (c) 2026 erik &lt;erik@erik.xyz&gt; — https://erik.xyz --&gt;
&lt;h1 id=&#34;Security-rust&#34;&gt;&lt;a href=&#34;#Security-rust&#34; class=&#34;headerlink&#34; title=&#34;Security rust&#34;&gt;&lt;/a&gt;Security rust&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-rust/blob/main/README.en.md&#34;&gt;English&lt;/a&gt; | &lt;strong&gt;中文&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;An attack detection library written in Rust, covering 27 detectors across 4 categories: injection attacks, protocol attacks, data/serialization attacks, and file/sensitive data leaks. Zero external framework dependencies, pure string scanning.&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Design-philosophy&#34;&gt;&lt;a href=&#34;#Design-philosophy&#34; class=&#34;headerlink&#34; title=&#34;Design philosophy&#34;&gt;&lt;/a&gt;Design philosophy&lt;/h2&gt;&lt;h3 id=&#34;Why-“detection”-rather-than-“blocking”&#34;&gt;&lt;a href=&#34;#Why-“detection”-rather-than-“blocking”&#34; class=&#34;headerlink&#34; title=&#34;Why “detection” rather than “blocking”&#34;&gt;&lt;/a&gt;Why “detection” rather than “blocking”&lt;/h3&gt;&lt;p&gt;This library is positioned as a &lt;strong&gt;pure input scanner&lt;/strong&gt; — it takes a string and returns structured detection results. It binds to no web framework, does no HTTP request/response parsing, and implements no real-time blocking. That way you can embed it in any pipeline: a WAF rule engine, log auditing, pre-flight validation in an API gateway, a CLI security scanner, and so on.&lt;br&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 id=&#34;Architectural-principles&#34;&gt;&lt;a href=&#34;#Architectural-principles&#34; class=&#34;headerlink&#34; title=&#34;Architectural principles&#34;&gt;&lt;/a&gt;Architectural principles&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Single responsibility&lt;/strong&gt; — each detector handles exactly one attack type and internally holds a compiled set of regex patterns&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;One interface&lt;/strong&gt; — the &lt;code&gt;Detector&lt;/code&gt; trait is the only contract every detector implements: &lt;code&gt;fn detect(&amp;amp;self, input: &amp;amp;str) -&amp;gt; Option&amp;lt;DetectionResult&amp;gt;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Default coverage&lt;/strong&gt; — &lt;code&gt;Scanner::default()&lt;/code&gt; wires up all 27 detectors in one call, usable with zero configuration&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Optional configuration&lt;/strong&gt; — &lt;code&gt;Scanner::builder()&lt;/code&gt; supports on-demand customization, assembling detectors selectively with &lt;code&gt;.with_detector()&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Trade-offs&#34;&gt;&lt;a href=&#34;#Trade-offs&#34; class=&#34;headerlink&#34; title=&#34;Trade-offs&#34;&gt;&lt;/a&gt;Trade-offs&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Decision&lt;/th&gt;
&lt;th&gt;Choice&lt;/th&gt;
&lt;th&gt;Rationale&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Regex vs. parser&lt;/td&gt;
&lt;td&gt;Regex&lt;/td&gt;
&lt;td&gt;In detection scenarios speed comes first, and regex covers mutated/bypass patterns better&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;First hit wins vs. scan everything&lt;/td&gt;
&lt;td&gt;Scan everything&lt;/td&gt;
&lt;td&gt;One input can trigger several attack types at once — nothing should be missed&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Zero dependencies vs. pulling in serde&lt;/td&gt;
&lt;td&gt;Zero dependencies&lt;/td&gt;
&lt;td&gt;Only depends on &lt;code&gt;regex&lt;/code&gt; + &lt;code&gt;thiserror&lt;/code&gt;: fast to compile, small footprint&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Architecture&#34;&gt;&lt;a href=&#34;#Architecture&#34; class=&#34;headerlink&#34; title=&#34;Architecture&#34;&gt;&lt;/a&gt;Architecture&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                     ┌──────────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │             Scanner              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  ┌────────────────────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  user input ───────►│  │ scan(input)                │  │      Vec&amp;lt;DetectionResult&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │ scan_with(input, &amp;amp;[...])   │──┼──►──────────────────────►&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  └─────────────┬──────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │                │                  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  ┌─────────────▼──────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   Vec&amp;lt;Box&amp;lt;dyn Detector&amp;gt;&amp;gt;   │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ XssDetector           │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ SqlInjectionDetector  │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ ... ×27               │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  └────────────────────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     └──────────────┬───────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ┌──────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │       Detector trait         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │  fn name(&amp;amp;self) -&amp;gt; &amp;amp;str      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │  fn detect(&amp;amp;self, &amp;amp;str)      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │       -&amp;gt; Option&amp;lt;Result&amp;gt;      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     └──────────────┬───────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ┌──────────────┼──────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │              │              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌────┴────┐  ┌──────┴──────┐  ┌───┴────┐  ┌────┴────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│injection│  │  protocol   │  │  data  │  │  file   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   10    │  │      9      │  │   5    │  │    3    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────┘  └─────────────┘  └────────┘  └─────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Module-responsibilities&#34;&gt;&lt;a href=&#34;#Module-responsibilities&#34; class=&#34;headerlink&#34; title=&#34;Module responsibilities&#34;&gt;&lt;/a&gt;Module responsibilities&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Module&lt;/th&gt;
&lt;th&gt;Path&lt;/th&gt;
&lt;th&gt;Detectors&lt;/th&gt;
&lt;th&gt;Responsibility&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Core&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/lib.rs&lt;/code&gt; &lt;code&gt;result.rs&lt;/code&gt; &lt;code&gt;scanner.rs&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Detector&lt;/code&gt; trait, &lt;code&gt;DetectionResult&lt;/code&gt;, &lt;code&gt;Scanner&lt;/code&gt;/&lt;code&gt;ScannerBuilder&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Injection&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/injection/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;10&lt;/td&gt;
&lt;td&gt;XSS, SQL injection, command injection, NoSQL, LDAP, XPATH, JNDI, SSI, GraphQL, SSTI&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Protocol&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/protocol/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;SSRF, XXE, header injection, host header attack, request smuggling, open redirect, CORS, WebSocket, DNS rebinding&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Data&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/data/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;PHP deserialization, CSV formula injection, mail header injection, JWT attack, prototype pollution&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;File&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/file/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;Path traversal, malicious file upload, sensitive data leak&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Detection-result-structure&#34;&gt;&lt;a href=&#34;#Detection-result-structure&#34; class=&#34;headerlink&#34; title=&#34;Detection result structure&#34;&gt;&lt;/a&gt;Detection result structure&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;struct&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DetectionResult&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; attack_type: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,      &lt;span class=&#34;comment&#34;&gt;// &amp;quot;xss&amp;quot;, &amp;quot;sql_injection&amp;quot; ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; category: AttackCategory, &lt;span class=&#34;comment&#34;&gt;// Injection | Protocol | Data | File&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; severity: Severity,       &lt;span class=&#34;comment&#34;&gt;// Critical | High | Medium | Low&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; matched_pattern: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,  &lt;span class=&#34;comment&#34;&gt;// the specific pattern fragment that matched&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; offset: &lt;span class=&#34;type&#34;&gt;usize&lt;/span&gt;,            &lt;span class=&#34;comment&#34;&gt;// byte offset into the input&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; message: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,          &lt;span class=&#34;comment&#34;&gt;// human-readable description&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;What-it-implements&#34;&gt;&lt;a href=&#34;#What-it-implements&#34; class=&#34;headerlink&#34; title=&#34;What it implements&#34;&gt;&lt;/a&gt;What it implements&lt;/h2&gt;&lt;h3 id=&#34;Injection-attacks-10-detectors&#34;&gt;&lt;a href=&#34;#Injection-attacks-10-detectors&#34; class=&#34;headerlink&#34; title=&#34;Injection attacks (10 detectors)&#34;&gt;&lt;/a&gt;Injection attacks (10 detectors)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Patterns covered&lt;/th&gt;
&lt;th&gt;Severity&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xss&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;script&amp;gt;&lt;/code&gt;, event handlers such as &lt;code&gt;onerror=&lt;/code&gt;, &lt;code&gt;javascript:&lt;/code&gt; pseudo-protocol, &lt;code&gt;&amp;lt;svg&amp;gt;&lt;/code&gt;/&lt;code&gt;&amp;lt;iframe&amp;gt;&lt;/code&gt; tags, CSS &lt;code&gt;expression()&lt;/code&gt;, &lt;code&gt;eval()&lt;/code&gt;, &lt;code&gt;document.cookie&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;sql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;UNION SELECT&lt;/code&gt;, time-based injection via &lt;code&gt;sleep()&lt;/code&gt;/&lt;code&gt;benchmark()&lt;/code&gt;/&lt;code&gt;pg_sleep()&lt;/code&gt;, &lt;code&gt;information_schema&lt;/code&gt; enumeration, &lt;code&gt;exec sp_&lt;/code&gt;/&lt;code&gt;xp_&lt;/code&gt; stored procedures, boolean blind patterns &lt;code&gt;&amp;#39; OR &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt;, &lt;code&gt;LOAD_FILE()&lt;/code&gt;/&lt;code&gt;INTO OUTFILE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;command_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Backtick commands, &lt;code&gt;$()&lt;/code&gt; subshells, chained execution through pipes, &lt;code&gt;/dev/tcp&lt;/code&gt; reverse shell, PHP functions &lt;code&gt;passthru()&lt;/code&gt;/&lt;code&gt;shell_exec()&lt;/code&gt;/&lt;code&gt;system()&lt;/code&gt;, &lt;code&gt;cmd.exe&lt;/code&gt;/&lt;code&gt;powershell&lt;/code&gt; invocation&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;nosql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;MongoDB &lt;code&gt;$ne&lt;/code&gt;/&lt;code&gt;$gt&lt;/code&gt;/&lt;code&gt;$regex&lt;/code&gt;/&lt;code&gt;$where&lt;/code&gt; operators, &lt;code&gt;$or&lt;/code&gt; injection, auth bypass with &lt;code&gt;&amp;#123;&amp;quot;$gt&amp;quot;: &amp;quot;&amp;quot;&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ldap_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;(&amp;amp;&lt;/code&gt; `(&lt;/td&gt;
&lt;td&gt;&lt;code&gt;`(!&lt;/code&gt; filter operators, &lt;code&gt;*(cn=&lt;/code&gt; attribute enumeration, &lt;code&gt;objectClass&lt;/code&gt;/&lt;code&gt;uid&lt;/code&gt; injection&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xpath_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#39; or &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt; boolean bypass, &lt;code&gt;&amp;#39; or true()&lt;/code&gt; function injection, `’]&lt;/td&gt;
&lt;td&gt;‘` node traversal&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;jndi_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;$&amp;#123;jndi:ldap://&lt;/code&gt;, &lt;code&gt;$&amp;#123;lower:j&amp;#125;&lt;/code&gt; obfuscation, &lt;code&gt;$&amp;#123;upper:j&amp;#125;&lt;/code&gt; obfuscation, &lt;code&gt;$&amp;#123;::-j&amp;#125;&lt;/code&gt; empty-string obfuscation, &lt;code&gt;$&amp;#123;env:&amp;#125;&lt;/code&gt; environment variable lookup, &lt;code&gt;$&amp;#123;sys:&amp;#125;&lt;/code&gt; system properties&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssi_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!--#exec cmd=&lt;/code&gt; command execution, &lt;code&gt;&amp;lt;!--#include file=&lt;/code&gt; file inclusion, &lt;code&gt;&amp;lt;!--#echo var=&lt;/code&gt; variable output, &lt;code&gt;&amp;lt;!--#fsize&lt;/code&gt;/&lt;code&gt;&amp;lt;!--#flastmod&lt;/code&gt; file information&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;graphql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__schema&lt;/code&gt;/&lt;code&gt;__type&lt;/code&gt; introspection queries, deeply nested DoS (≥5 levels)&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssti&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Jinja2 &lt;code&gt;&amp;#123;&amp;#123;&amp;#125;&amp;#125;&lt;/code&gt;, FreeMarker &lt;code&gt;$&amp;#123;&amp;#125;&lt;/code&gt;, ERB &lt;code&gt;&amp;lt;%=&lt;/code&gt; &lt;code&gt;&amp;lt;%@&lt;/code&gt;, Velocity &lt;code&gt;#set()&lt;/code&gt;, Python MRO sandbox escape via &lt;code&gt;__mro__&lt;/code&gt;/&lt;code&gt;__subclasses__()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Protocol-and-request-attacks-9-detectors&#34;&gt;&lt;a href=&#34;#Protocol-and-request-attacks-9-detectors&#34; class=&#34;headerlink&#34; title=&#34;Protocol and request attacks (9 detectors)&#34;&gt;&lt;/a&gt;Protocol and request attacks (9 detectors)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Patterns covered&lt;/th&gt;
&lt;th&gt;Severity&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssrf&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;169.254.169.254&lt;/code&gt; cloud metadata, RFC1918 private IPs (10.x, 172.16-31.x, 192.168.x), &lt;code&gt;127.x&lt;/code&gt; loopback, &lt;code&gt;::1&lt;/code&gt; IPv6 loopback, &lt;code&gt;0.0.0.0&lt;/code&gt;, dangerous protocols &lt;code&gt;gopher://&lt;/code&gt;/&lt;code&gt;dict://&lt;/code&gt;/&lt;code&gt;ftp://&lt;/code&gt;/&lt;code&gt;file://&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xxe&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!ENTITY&lt;/code&gt; entity declarations, &lt;code&gt;SYSTEM&lt;/code&gt;/&lt;code&gt;PUBLIC&lt;/code&gt; external references, &lt;code&gt;%&lt;/code&gt; parameter entities, &lt;code&gt;&amp;lt;!DOCTYPE&lt;/code&gt; DTD declarations&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;header_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;%0d%0a&lt;/code&gt; URL-encoded CRLF, raw &lt;code&gt;\r\n&lt;/code&gt; CRLF injection&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;host_header&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Multiple Host headers, &lt;code&gt;X-Forwarded-Host&lt;/code&gt;/&lt;code&gt;X-Original-URL&lt;/code&gt;/&lt;code&gt;X-Rewrite-URL&lt;/code&gt; poisoning, CRLF carrying a Host&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;request_smuggling&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Duplicate &lt;code&gt;Transfer-Encoding&lt;/code&gt; headers, &lt;code&gt;Content-Length: 0&lt;/code&gt; smuggling, &lt;code&gt;\r\n0\r\n&lt;/code&gt; chunked terminator obfuscation&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;open_redirect&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;//evil.com&lt;/code&gt; protocol-relative URLs, &lt;code&gt;javascript:&lt;/code&gt;/&lt;code&gt;data:text/html&lt;/code&gt; pseudo-protocol redirects&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;cors&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Origin: null&lt;/code&gt; bypass, the &lt;code&gt;Access-Control-Allow-Origin: *&lt;/code&gt; + Credentials combination&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;websocket&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Upgrade: websocket&lt;/code&gt; handshakes, cross-origin WS with &lt;code&gt;Origin: null&lt;/code&gt;, plaintext &lt;code&gt;ws://&lt;/code&gt; connections&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;dns_rebinding&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Host header set to a private IP &lt;code&gt;127.x&lt;/code&gt;/&lt;code&gt;10.x&lt;/code&gt;/&lt;code&gt;192.168.x&lt;/code&gt;/&lt;code&gt;172.16-31.x&lt;/code&gt;, &lt;code&gt;localhost&lt;/code&gt;, &lt;code&gt;::1&lt;/code&gt;, &lt;code&gt;0.0.0.0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Data-and-serialization-attacks-5-detectors&#34;&gt;&lt;a href=&#34;#Data-and-serialization-attacks-5-detectors&#34; class=&#34;headerlink&#34; title=&#34;Data and serialization attacks (5 detectors)&#34;&gt;&lt;/a&gt;Data and serialization attacks (5 detectors)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Patterns covered&lt;/th&gt;
&lt;th&gt;Severity&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;deserialization&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;PHP &lt;code&gt;O:number:&lt;/code&gt;/&lt;code&gt;C:number:&lt;/code&gt; serialized objects, &lt;code&gt;a:number:&amp;#123;&lt;/code&gt; arrays, &lt;code&gt;unserialize()&lt;/code&gt; calls, magic methods such as &lt;code&gt;__wakeup&lt;/code&gt;/&lt;code&gt;__destruct&lt;/code&gt;/&lt;code&gt;__toString&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;csv_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Leading formula characters &lt;code&gt;=&lt;/code&gt;/&lt;code&gt;+&lt;/code&gt;/&lt;code&gt;-&lt;/code&gt;/&lt;code&gt;@&lt;/code&gt;, DDE dynamic data exchange, `cmd&lt;/td&gt;
&lt;td&gt;&lt;code&gt;command pipes,&lt;/code&gt;@SUM()` functions&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;mail_header&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Bcc:&lt;/code&gt;/&lt;code&gt;Cc:&lt;/code&gt; blind-carbon-copy injection, multiple &lt;code&gt;From:&lt;/code&gt; senders, &lt;code&gt;MIME-Version:&lt;/code&gt;/&lt;code&gt;Content-Type: multipart&lt;/code&gt; MIME header injection, &lt;code&gt;boundary=&lt;/code&gt; manipulation&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;jwt_attack&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;alg: none&lt;/code&gt; empty-algorithm bypass, &lt;code&gt;kid&lt;/code&gt; path traversal injection, empty signature segment, empty payload segment&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;prototype_pollution&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__proto__&lt;/code&gt;/&lt;code&gt;constructor.prototype&lt;/code&gt; prototype chain pollution, &lt;code&gt;__defineGetter__&lt;/code&gt;/&lt;code&gt;__defineSetter__&lt;/code&gt;/&lt;code&gt;__lookupGetter__&lt;/code&gt;/&lt;code&gt;__lookupSetter__&lt;/code&gt; property hijacking&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Files-and-sensitive-data-3-detectors&#34;&gt;&lt;a href=&#34;#Files-and-sensitive-data-3-detectors&#34; class=&#34;headerlink&#34; title=&#34;Files and sensitive data (3 detectors)&#34;&gt;&lt;/a&gt;Files and sensitive data (3 detectors)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Patterns covered&lt;/th&gt;
&lt;th&gt;Severity&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;path_traversal&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;../&lt;/code&gt;/&lt;code&gt;..\\&lt;/code&gt; directory traversal, &lt;code&gt;%2e%2e&lt;/code&gt; URL-encoded bypass, &lt;code&gt;php://filter&lt;/code&gt;/&lt;code&gt;php://input&lt;/code&gt;/&lt;code&gt;phar://&lt;/code&gt;/&lt;code&gt;zip://&lt;/code&gt;/&lt;code&gt;data://&lt;/code&gt;/&lt;code&gt;expect://&lt;/code&gt;/&lt;code&gt;glob://&lt;/code&gt; stream wrappers, &lt;code&gt;%00&lt;/code&gt; null byte truncation&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;upload&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;?php&lt;/code&gt;/&lt;code&gt;&amp;lt;?=&lt;/code&gt; PHP tags, &lt;code&gt;&amp;lt;%@&lt;/code&gt;/&lt;code&gt;&amp;lt;%=&lt;/code&gt; ASP tags, backdoor patterns &lt;code&gt;eval($_&lt;/code&gt;/&lt;code&gt;system($_&lt;/code&gt;/&lt;code&gt;exec($_&lt;/code&gt;/&lt;code&gt;passthru($_&lt;/code&gt;, superglobals &lt;code&gt;$_GET&lt;/code&gt;/&lt;code&gt;$_POST&lt;/code&gt;/&lt;code&gt;$_REQUEST&lt;/code&gt;/&lt;code&gt;$_SERVER&lt;/code&gt;, &lt;code&gt;base64_decode()&lt;/code&gt; encoding bypass&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;data_leak&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;16-digit credit card PANs (Visa/MasterCard/AmEx/Discover/JCB/Diners), AWS Access Keys &lt;code&gt;AKIA...&lt;/code&gt;, PEM private key headers &lt;code&gt;-----BEGIN&lt;/code&gt;, OpenAI/LLM API keys &lt;code&gt;sk-...&lt;/code&gt;, database connection strings &lt;code&gt;mongodb://&lt;/code&gt;/&lt;code&gt;mysql://&lt;/code&gt;/&lt;code&gt;postgresql://&lt;/code&gt;/&lt;code&gt;redis://&lt;/code&gt;/&lt;code&gt;jdbc:&lt;/code&gt;, JWT tokens&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Usage&#34;&gt;&lt;a href=&#34;#Usage&#34; class=&#34;headerlink&#34; title=&#34;Usage&#34;&gt;&lt;/a&gt;Usage&lt;/h2&gt;&lt;h3 id=&#34;Installation&#34;&gt;&lt;a href=&#34;#Installation&#34; class=&#34;headerlink&#34; title=&#34;Installation&#34;&gt;&lt;/a&gt;Installation&lt;/h3&gt;&lt;figure class=&#34;highlight toml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;[dependencies]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;security-rust&lt;/span&gt; = &amp;#123; path = &lt;span class=&#34;string&#34;&gt;&amp;quot;.&amp;quot;&lt;/span&gt; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Quick-start&#34;&gt;&lt;a href=&#34;#Quick-start&#34; class=&#34;headerlink&#34; title=&#34;Quick start&#34;&gt;&lt;/a&gt;Quick start&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::Scanner;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;() &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// Zero config: assembles all 27 detectors&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;default&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// Scan the input, returning every attack detected&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;results&lt;/span&gt; = scanner.&lt;span class=&#34;title function_ invoke__&#34;&gt;scan&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;lt;script&amp;gt;alert(&amp;#x27;xss&amp;#x27;)&amp;lt;/script&amp;gt;&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;r&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &amp;amp;results &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;println!&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;[&amp;#123;&amp;#125;] &amp;#123;&amp;#125; — offset: &amp;#123;&amp;#125;, pattern: &amp;#123;&amp;#125;&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            r.severity, r.message, r.offset, r.matched_pattern);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// Output:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// [CRITICAL] XSS cross-site scripting detected — offset: 0, pattern: &amp;lt;script&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Selective-scanning&#34;&gt;&lt;a href=&#34;#Selective-scanning&#34; class=&#34;headerlink&#34; title=&#34;Selective scanning&#34;&gt;&lt;/a&gt;Selective scanning&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;default&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// Run only the detectors you name&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;results&lt;/span&gt; = scanner.&lt;span class=&#34;title function_ invoke__&#34;&gt;scan_with&lt;/span&gt;(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;1 UNION SELECT password FROM users&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;amp;[&lt;span class=&#34;string&#34;&gt;&amp;quot;sql_injection&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;xss&amp;quot;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;);&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Custom-configuration&#34;&gt;&lt;a href=&#34;#Custom-configuration&#34; class=&#34;headerlink&#34; title=&#34;Custom configuration&#34;&gt;&lt;/a&gt;Custom configuration&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::injection::&amp;#123;XssDetector, SqlInjectionDetector&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// Use the builder to assemble only the detectors you need&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(XssDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(SqlInjectionDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Assembling-only-some-detectors&#34;&gt;&lt;a href=&#34;#Assembling-only-some-detectors&#34; class=&#34;headerlink&#34; title=&#34;Assembling only some detectors&#34;&gt;&lt;/a&gt;Assembling only some detectors&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::injection::&amp;#123;XssDetector, SqlInjectionDetector&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(XssDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(SqlInjectionDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Displaying-severity&#34;&gt;&lt;a href=&#34;#Displaying-severity&#34; class=&#34;headerlink&#34; title=&#34;Displaying severity&#34;&gt;&lt;/a&gt;Displaying severity&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::Severity;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;r&lt;/span&gt; = &amp;amp;results[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;println!&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#123;&amp;#125;&amp;quot;&lt;/span&gt;, r.severity);  &lt;span class=&#34;comment&#34;&gt;// CRITICAL | HIGH | MEDIUM | LOW&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Performance&#34;&gt;&lt;a href=&#34;#Performance&#34; class=&#34;headerlink&#34; title=&#34;Performance&#34;&gt;&lt;/a&gt;Performance&lt;/h3&gt;&lt;p&gt;In a release build, a single detector scans in ~100ns per call (precompiled RegexSet), and all 27 detectors together scan in about ~5μs per call. That makes it a good fit for high-throughput scenarios (API gateways, log pipelines).&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;Development&#34;&gt;&lt;a href=&#34;#Development&#34; class=&#34;headerlink&#34; title=&#34;Development&#34;&gt;&lt;/a&gt;Development&lt;/h2&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Build&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo build --release&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Test (46 integration tests)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo &lt;span class=&#34;built_in&#34;&gt;test&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Lint&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo clippy -- -D warnings&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;License&#34;&gt;&lt;a href=&#34;#License&#34; class=&#34;headerlink&#34; title=&#34;License&#34;&gt;&lt;/a&gt;License&lt;/h2&gt;&lt;p&gt;MIT — Copyright (c) 2026 erik &lt;a href=&#34;&amp;#109;&amp;#97;&amp;#x69;&amp;#108;&amp;#x74;&amp;#111;&amp;#58;&amp;#101;&amp;#114;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#x72;&amp;#105;&amp;#107;&amp;#x2e;&amp;#120;&amp;#121;&amp;#122;&#34;&gt;&amp;#101;&amp;#114;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#x72;&amp;#105;&amp;#107;&amp;#x2e;&amp;#120;&amp;#121;&amp;#122;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;

 &lt;!-- Copyright (c) 2026 erik &lt;erik@erik.xyz&gt; — https://erik.xyz --&gt;
&lt;h1 id=&#34;Security-rust&#34;&gt;&lt;a href=&#34;#Security-rust&#34; class=&#34;headerlink&#34; title=&#34;Security rust&#34;&gt;&lt;/a&gt;Security rust&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-rust/blob/main/README.en.md&#34;&gt;English&lt;/a&gt; | &lt;strong&gt;中文&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Rust 编写的攻击检测库，覆盖注入攻击、协议攻击、数据/序列化攻击、文件/敏感数据泄露 4 大类共 27 个检测器。零外部框架依赖，纯字符串扫描。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;设计思路&#34;&gt;&lt;a href=&#34;#设计思路&#34; class=&#34;headerlink&#34; title=&#34;设计思路&#34;&gt;&lt;/a&gt;设计思路&lt;/h2&gt;&lt;h3 id=&#34;为什么用「检测」而非「拦截」&#34;&gt;&lt;a href=&#34;#为什么用「检测」而非「拦截」&#34; class=&#34;headerlink&#34; title=&#34;为什么用「检测」而非「拦截」&#34;&gt;&lt;/a&gt;为什么用「检测」而非「拦截」&lt;/h3&gt;&lt;p&gt;本库定位为&lt;strong&gt;纯输入扫描器&lt;/strong&gt;——接收字符串，返回结构化检测结果。不绑定任何 Web 框架，不做 HTTP 请求/响应解析，不实现实时阻断。这样你可以把它嵌入到任何链路中：WAF 规则引擎、日志审计、API 网关前置校验、CLI 安全扫描工具等。&lt;br&gt;&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 id=&#34;架构原则&#34;&gt;&lt;a href=&#34;#架构原则&#34; class=&#34;headerlink&#34; title=&#34;架构原则&#34;&gt;&lt;/a&gt;架构原则&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;单一职责&lt;/strong&gt; — 每个检测器只管一种攻击类型，内部持有编译好的正则模式集&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;统一接口&lt;/strong&gt; — &lt;code&gt;Detector&lt;/code&gt; trait 是所有检测器的唯一契约：&lt;code&gt;fn detect(&amp;amp;self, input: &amp;amp;str) -&amp;gt; Option&amp;lt;DetectionResult&amp;gt;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;默认覆盖&lt;/strong&gt; — &lt;code&gt;Scanner::default()&lt;/code&gt; 一键装配全部 27 个检测器，零配置可用&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;可选配置&lt;/strong&gt; — &lt;code&gt;Scanner::builder()&lt;/code&gt; 支持按需定制，通过 &lt;code&gt;.with_detector()&lt;/code&gt; 选择性装配检测器&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;权衡&#34;&gt;&lt;a href=&#34;#权衡&#34; class=&#34;headerlink&#34; title=&#34;权衡&#34;&gt;&lt;/a&gt;权衡&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;决策&lt;/th&gt;
&lt;th&gt;选择&lt;/th&gt;
&lt;th&gt;理由&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;正则 vs 解析器&lt;/td&gt;
&lt;td&gt;正则&lt;/td&gt;
&lt;td&gt;检测场景下速度优先，正则对变形/绕过模式的覆盖更好&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;先到先报 vs 全量检测&lt;/td&gt;
&lt;td&gt;全量检测&lt;/td&gt;
&lt;td&gt;一个输入可能同时触发多种攻击，不应漏报&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;零依赖 vs 引入 serde&lt;/td&gt;
&lt;td&gt;零依赖&lt;/td&gt;
&lt;td&gt;只依赖 &lt;code&gt;regex&lt;/code&gt; + &lt;code&gt;thiserror&lt;/code&gt;，编译快、体积小&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;h2 id=&#34;设计架构&#34;&gt;&lt;a href=&#34;#设计架构&#34; class=&#34;headerlink&#34; title=&#34;设计架构&#34;&gt;&lt;/a&gt;设计架构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                     ┌──────────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │             Scanner              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  ┌────────────────────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  user input ───────►│  │ scan(input)                │  │      Vec&amp;lt;DetectionResult&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │ scan_with(input, &amp;amp;[...])   │──┼──►──────────────────────►&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  └─────────────┬──────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │                │                  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  ┌─────────────▼──────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   Vec&amp;lt;Box&amp;lt;dyn Detector&amp;gt;&amp;gt;   │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ XssDetector           │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ SqlInjectionDetector  │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  │   ├─ ... ×27               │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     │  └────────────────────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                     └──────────────┬───────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ┌──────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │       Detector trait         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │  fn name(&amp;amp;self) -&amp;gt; &amp;amp;str      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │  fn detect(&amp;amp;self, &amp;amp;str)      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │       -&amp;gt; Option&amp;lt;Result&amp;gt;      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     └──────────────┬───────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ┌──────────────┼──────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │              │              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌────┴────┐  ┌──────┴──────┐  ┌───┴────┐  ┌────┴────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│injection│  │  protocol   │  │  data  │  │  file   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  10 个  │  │   9 个      │  │ 5 个   │  │  3 个   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────┘  └─────────────┘  └────────┘  └─────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;模块职责&#34;&gt;&lt;a href=&#34;#模块职责&#34; class=&#34;headerlink&#34; title=&#34;模块职责&#34;&gt;&lt;/a&gt;模块职责&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;模块&lt;/th&gt;
&lt;th&gt;路径&lt;/th&gt;
&lt;th&gt;检测器数&lt;/th&gt;
&lt;th&gt;职责&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;核心&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/lib.rs&lt;/code&gt; &lt;code&gt;result.rs&lt;/code&gt; &lt;code&gt;scanner.rs&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;—&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Detector&lt;/code&gt; trait、&lt;code&gt;DetectionResult&lt;/code&gt;、&lt;code&gt;Scanner&lt;/code&gt;/&lt;code&gt;ScannerBuilder&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;注入&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/injection/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;10&lt;/td&gt;
&lt;td&gt;XSS、SQL 注入、命令注入、NoSQL、LDAP、XPATH、JNDI、SSI、GraphQL、SSTI&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;协议&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/protocol/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;9&lt;/td&gt;
&lt;td&gt;SSRF、XXE、Header 注入、Host 头攻击、请求走私、开放重定向、CORS、WebSocket、DNS 重绑定&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;数据&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/data/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;5&lt;/td&gt;
&lt;td&gt;PHP 反序列化、CSV 公式注入、邮件头注入、JWT 攻击、原型污染&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;文件&lt;/td&gt;
&lt;td&gt;&lt;code&gt;src/file/&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;3&lt;/td&gt;
&lt;td&gt;路径遍历、恶意文件上传、敏感数据泄露&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;检测结果结构&#34;&gt;&lt;a href=&#34;#检测结果结构&#34; class=&#34;headerlink&#34; title=&#34;检测结果结构&#34;&gt;&lt;/a&gt;检测结果结构&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;struct&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;DetectionResult&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; attack_type: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,      &lt;span class=&#34;comment&#34;&gt;// &amp;quot;xss&amp;quot;, &amp;quot;sql_injection&amp;quot; ...&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; category: AttackCategory, &lt;span class=&#34;comment&#34;&gt;// Injection | Protocol | Data | File&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; severity: Severity,       &lt;span class=&#34;comment&#34;&gt;// Critical | High | Medium | Low&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; matched_pattern: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,  &lt;span class=&#34;comment&#34;&gt;// 匹配到的具体模式片段&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; offset: &lt;span class=&#34;type&#34;&gt;usize&lt;/span&gt;,            &lt;span class=&#34;comment&#34;&gt;// 输入中的字节偏移&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;pub&lt;/span&gt; message: &lt;span class=&#34;type&#34;&gt;String&lt;/span&gt;,          &lt;span class=&#34;comment&#34;&gt;// 人类可读说明&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;实现功能&#34;&gt;&lt;a href=&#34;#实现功能&#34; class=&#34;headerlink&#34; title=&#34;实现功能&#34;&gt;&lt;/a&gt;实现功能&lt;/h2&gt;&lt;h3 id=&#34;注入类攻击（10-个检测器）&#34;&gt;&lt;a href=&#34;#注入类攻击（10-个检测器）&#34; class=&#34;headerlink&#34; title=&#34;注入类攻击（10 个检测器）&#34;&gt;&lt;/a&gt;注入类攻击（10 个检测器）&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;覆盖模式&lt;/th&gt;
&lt;th&gt;严重度&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xss&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;script&amp;gt;&lt;/code&gt;、&lt;code&gt;onerror=&lt;/code&gt; 等事件处理器、&lt;code&gt;javascript:&lt;/code&gt; 伪协议、&lt;code&gt;&amp;lt;svg&amp;gt;&lt;/code&gt;/&lt;code&gt;&amp;lt;iframe&amp;gt;&lt;/code&gt; 标签、CSS &lt;code&gt;expression()&lt;/code&gt;、&lt;code&gt;eval()&lt;/code&gt;、&lt;code&gt;document.cookie&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;sql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;UNION SELECT&lt;/code&gt;、&lt;code&gt;sleep()&lt;/code&gt;/&lt;code&gt;benchmark()&lt;/code&gt;/&lt;code&gt;pg_sleep()&lt;/code&gt; 延时注入、&lt;code&gt;information_schema&lt;/code&gt; 枚举、&lt;code&gt;exec sp_&lt;/code&gt;/&lt;code&gt;xp_&lt;/code&gt; 存储过程、布尔盲注模式 &lt;code&gt;&amp;#39; OR &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt;、&lt;code&gt;LOAD_FILE()&lt;/code&gt;/&lt;code&gt;INTO OUTFILE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;command_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;反引号命令、&lt;code&gt;$()&lt;/code&gt; 子命令、管道符链式执行、&lt;code&gt;/dev/tcp&lt;/code&gt; 反弹 shell、&lt;code&gt;passthru()&lt;/code&gt;/&lt;code&gt;shell_exec()&lt;/code&gt;/&lt;code&gt;system()&lt;/code&gt; PHP 函数、&lt;code&gt;cmd.exe&lt;/code&gt;/&lt;code&gt;powershell&lt;/code&gt; 调用&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;nosql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;MongoDB &lt;code&gt;$ne&lt;/code&gt;/&lt;code&gt;$gt&lt;/code&gt;/&lt;code&gt;$regex&lt;/code&gt;/&lt;code&gt;$where&lt;/code&gt; 操作符、&lt;code&gt;$or&lt;/code&gt; 注入、认证绕过 &lt;code&gt;&amp;#123;&amp;quot;$gt&amp;quot;: &amp;quot;&amp;quot;&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ldap_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;(&amp;amp;&lt;/code&gt; `(&lt;/td&gt;
&lt;td&gt;&lt;code&gt;`(!&lt;/code&gt; 过滤操作符、&lt;code&gt;*(cn=&lt;/code&gt; 属性枚举、&lt;code&gt;objectClass&lt;/code&gt;/&lt;code&gt;uid&lt;/code&gt; 注入&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xpath_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;#39; or &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt; 布尔绕过、&lt;code&gt;&amp;#39; or true()&lt;/code&gt; 函数注入、`’]&lt;/td&gt;
&lt;td&gt;‘` 节点遍历&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;jndi_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;$&amp;#123;jndi:ldap://&lt;/code&gt;、&lt;code&gt;$&amp;#123;lower:j&amp;#125;&lt;/code&gt; 混淆、&lt;code&gt;$&amp;#123;upper:j&amp;#125;&lt;/code&gt; 混淆、&lt;code&gt;$&amp;#123;::-j&amp;#125;&lt;/code&gt; 空字符串混淆、&lt;code&gt;$&amp;#123;env:&amp;#125;&lt;/code&gt; 环境变量查找、&lt;code&gt;$&amp;#123;sys:&amp;#125;&lt;/code&gt; 系统属性&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssi_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!--#exec cmd=&lt;/code&gt; 命令执行、&lt;code&gt;&amp;lt;!--#include file=&lt;/code&gt; 文件包含、&lt;code&gt;&amp;lt;!--#echo var=&lt;/code&gt; 变量输出、&lt;code&gt;&amp;lt;!--#fsize&lt;/code&gt;/&lt;code&gt;&amp;lt;!--#flastmod&lt;/code&gt; 文件信息&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;graphql_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__schema&lt;/code&gt;/&lt;code&gt;__type&lt;/code&gt; 内省查询、深度嵌套 DoS（≥5层）&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssti&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Jinja2 &lt;code&gt;&amp;#123;&amp;#123;&amp;#125;&amp;#125;&lt;/code&gt;、FreeMarker &lt;code&gt;$&amp;#123;&amp;#125;&lt;/code&gt;、ERB &lt;code&gt;&amp;lt;%=&lt;/code&gt; &lt;code&gt;&amp;lt;%@&lt;/code&gt;、Velocity &lt;code&gt;#set()&lt;/code&gt;、Python MRO &lt;code&gt;__mro__&lt;/code&gt;/&lt;code&gt;__subclasses__()&lt;/code&gt; 沙箱逃逸&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;协议与请求攻击（9-个检测器）&#34;&gt;&lt;a href=&#34;#协议与请求攻击（9-个检测器）&#34; class=&#34;headerlink&#34; title=&#34;协议与请求攻击（9 个检测器）&#34;&gt;&lt;/a&gt;协议与请求攻击（9 个检测器）&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;覆盖模式&lt;/th&gt;
&lt;th&gt;严重度&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ssrf&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;169.254.169.254&lt;/code&gt; 云元数据、RFC1918 内网 IP（10.x、172.16-31.x、192.168.x）、&lt;code&gt;127.x&lt;/code&gt; loopback、&lt;code&gt;::1&lt;/code&gt; IPv6 loopback、&lt;code&gt;0.0.0.0&lt;/code&gt;、&lt;code&gt;gopher://&lt;/code&gt;/&lt;code&gt;dict://&lt;/code&gt;/&lt;code&gt;ftp://&lt;/code&gt;/&lt;code&gt;file://&lt;/code&gt; 危险协议&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;xxe&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!ENTITY&lt;/code&gt; 实体声明、&lt;code&gt;SYSTEM&lt;/code&gt;/&lt;code&gt;PUBLIC&lt;/code&gt; 外部引用、&lt;code&gt;%&lt;/code&gt; 参数实体、&lt;code&gt;&amp;lt;!DOCTYPE&lt;/code&gt; DTD 声明&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;header_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;%0d%0a&lt;/code&gt; URL 编码 CRLF、&lt;code&gt;\r\n&lt;/code&gt; 原始 CRLF 注入&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;host_header&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;多 Host 头注入、&lt;code&gt;X-Forwarded-Host&lt;/code&gt;/&lt;code&gt;X-Original-URL&lt;/code&gt;/&lt;code&gt;X-Rewrite-URL&lt;/code&gt; 投毒、CRLF 携带 Host&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;request_smuggling&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;双重 &lt;code&gt;Transfer-Encoding&lt;/code&gt; 头、&lt;code&gt;Content-Length: 0&lt;/code&gt; 走私、&lt;code&gt;\r\n0\r\n&lt;/code&gt; chunked 终止混淆&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;open_redirect&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;//evil.com&lt;/code&gt; 协议相对 URL、&lt;code&gt;javascript:&lt;/code&gt;/&lt;code&gt;data:text/html&lt;/code&gt; 伪协议跳转&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;cors&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Origin: null&lt;/code&gt; 绕过、&lt;code&gt;Access-Control-Allow-Origin: *&lt;/code&gt; + Credentials 组合&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;websocket&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Upgrade: websocket&lt;/code&gt; 握手、&lt;code&gt;Origin: null&lt;/code&gt; 跨域 WS、&lt;code&gt;ws://&lt;/code&gt; 明文连接&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;dns_rebinding&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Host 头为 &lt;code&gt;127.x&lt;/code&gt;/&lt;code&gt;10.x&lt;/code&gt;/&lt;code&gt;192.168.x&lt;/code&gt;/&lt;code&gt;172.16-31.x&lt;/code&gt; 内网 IP、&lt;code&gt;localhost&lt;/code&gt;、&lt;code&gt;::1&lt;/code&gt;、&lt;code&gt;0.0.0.0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;数据与序列化攻击（5-个检测器）&#34;&gt;&lt;a href=&#34;#数据与序列化攻击（5-个检测器）&#34; class=&#34;headerlink&#34; title=&#34;数据与序列化攻击（5 个检测器）&#34;&gt;&lt;/a&gt;数据与序列化攻击（5 个检测器）&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;覆盖模式&lt;/th&gt;
&lt;th&gt;严重度&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;deserialization&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;PHP &lt;code&gt;O:数字:&lt;/code&gt;/&lt;code&gt;C:数字:&lt;/code&gt; 序列化对象、&lt;code&gt;a:数字:&amp;#123;&lt;/code&gt; 数组、&lt;code&gt;unserialize()&lt;/code&gt; 调用、&lt;code&gt;__wakeup&lt;/code&gt;/&lt;code&gt;__destruct&lt;/code&gt;/&lt;code&gt;__toString&lt;/code&gt; 等魔术方法&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;csv_injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;行首 &lt;code&gt;=&lt;/code&gt;/&lt;code&gt;+&lt;/code&gt;/&lt;code&gt;-&lt;/code&gt;/&lt;code&gt;@&lt;/code&gt; 公式字符、DDE 动态数据交换、`cmd&lt;/td&gt;
&lt;td&gt;&lt;code&gt;命令管道、&lt;/code&gt;@SUM()` 函数&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;mail_header&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Bcc:&lt;/code&gt;/&lt;code&gt;Cc:&lt;/code&gt; 密送注入、&lt;code&gt;From:&lt;/code&gt; 多重发件人、&lt;code&gt;MIME-Version:&lt;/code&gt;/&lt;code&gt;Content-Type: multipart&lt;/code&gt; MIME 头注入、&lt;code&gt;boundary=&lt;/code&gt; 边界操纵&lt;/td&gt;
&lt;td&gt;Medium&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;jwt_attack&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;alg: none&lt;/code&gt; 空算法绕过、&lt;code&gt;kid&lt;/code&gt; 路径遍历注入、空签名段、空 payload 段&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;prototype_pollution&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__proto__&lt;/code&gt;/&lt;code&gt;constructor.prototype&lt;/code&gt; 原型链污染、&lt;code&gt;__defineGetter__&lt;/code&gt;/&lt;code&gt;__defineSetter__&lt;/code&gt;/&lt;code&gt;__lookupGetter__&lt;/code&gt;/&lt;code&gt;__lookupSetter__&lt;/code&gt; 属性劫持&lt;/td&gt;
&lt;td&gt;High&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;文件与敏感数据（3-个检测器）&#34;&gt;&lt;a href=&#34;#文件与敏感数据（3-个检测器）&#34; class=&#34;headerlink&#34; title=&#34;文件与敏感数据（3 个检测器）&#34;&gt;&lt;/a&gt;文件与敏感数据（3 个检测器）&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;覆盖模式&lt;/th&gt;
&lt;th&gt;严重度&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;path_traversal&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;../&lt;/code&gt;/&lt;code&gt;..\\&lt;/code&gt; 目录跨越、&lt;code&gt;%2e%2e&lt;/code&gt; URL 编码绕过、&lt;code&gt;php://filter&lt;/code&gt;/&lt;code&gt;php://input&lt;/code&gt;/&lt;code&gt;phar://&lt;/code&gt;/&lt;code&gt;zip://&lt;/code&gt;/&lt;code&gt;data://&lt;/code&gt;/&lt;code&gt;expect://&lt;/code&gt;/&lt;code&gt;glob://&lt;/code&gt; 协议包装器、&lt;code&gt;%00&lt;/code&gt; 空字节截断&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;upload&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;?php&lt;/code&gt;/&lt;code&gt;&amp;lt;?=&lt;/code&gt; PHP 标签、&lt;code&gt;&amp;lt;%@&lt;/code&gt;/&lt;code&gt;&amp;lt;%=&lt;/code&gt; ASP 标签、&lt;code&gt;eval($_&lt;/code&gt;/&lt;code&gt;system($_&lt;/code&gt;/&lt;code&gt;exec($_&lt;/code&gt;/&lt;code&gt;passthru($_&lt;/code&gt; 后门模式、&lt;code&gt;$_GET&lt;/code&gt;/&lt;code&gt;$_POST&lt;/code&gt;/&lt;code&gt;$_REQUEST&lt;/code&gt;/&lt;code&gt;$_SERVER&lt;/code&gt; 超全局变量、&lt;code&gt;base64_decode()&lt;/code&gt; 编码绕过&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;data_leak&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;16 位信用卡 PAN（Visa/MasterCard/AmEx/Discover/JCB/Diners）、AWS Access Key &lt;code&gt;AKIA...&lt;/code&gt;、PEM 私钥头 &lt;code&gt;-----BEGIN&lt;/code&gt;、OpenAI/LLM API Key &lt;code&gt;sk-...&lt;/code&gt;、数据库连接串 &lt;code&gt;mongodb://&lt;/code&gt;/&lt;code&gt;mysql://&lt;/code&gt;/&lt;code&gt;postgresql://&lt;/code&gt;/&lt;code&gt;redis://&lt;/code&gt;/&lt;code&gt;jdbc:&lt;/code&gt;、JWT Token&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;h2 id=&#34;使用说明&#34;&gt;&lt;a href=&#34;#使用说明&#34; class=&#34;headerlink&#34; title=&#34;使用说明&#34;&gt;&lt;/a&gt;使用说明&lt;/h2&gt;&lt;h3 id=&#34;安装&#34;&gt;&lt;a href=&#34;#安装&#34; class=&#34;headerlink&#34; title=&#34;安装&#34;&gt;&lt;/a&gt;安装&lt;/h3&gt;&lt;figure class=&#34;highlight toml&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;section&#34;&gt;[dependencies]&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attr&#34;&gt;security-rust&lt;/span&gt; = &amp;#123; path = &lt;span class=&#34;string&#34;&gt;&amp;quot;.&amp;quot;&lt;/span&gt; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::Scanner;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;fn&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;() &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 零配置：装配全部 27 个检测器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;default&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 扫描输入，返回所有检测到的攻击&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;results&lt;/span&gt; = scanner.&lt;span class=&#34;title function_ invoke__&#34;&gt;scan&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;lt;script&amp;gt;alert(&amp;#x27;xss&amp;#x27;)&amp;lt;/script&amp;gt;&amp;quot;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;r&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &amp;amp;results &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;built_in&#34;&gt;println!&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;[&amp;#123;&amp;#125;] &amp;#123;&amp;#125; — offset: &amp;#123;&amp;#125;, pattern: &amp;#123;&amp;#125;&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            r.severity, r.message, r.offset, r.matched_pattern);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 输出:&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// [CRITICAL] XSS cross-site scripting detected — offset: 0, pattern: &amp;lt;script&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;选择性扫描&#34;&gt;&lt;a href=&#34;#选择性扫描&#34; class=&#34;headerlink&#34; title=&#34;选择性扫描&#34;&gt;&lt;/a&gt;选择性扫描&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;default&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 只运行指定的检测器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;results&lt;/span&gt; = scanner.&lt;span class=&#34;title function_ invoke__&#34;&gt;scan_with&lt;/span&gt;(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;1 UNION SELECT password FROM users&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;amp;[&lt;span class=&#34;string&#34;&gt;&amp;quot;sql_injection&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;xss&amp;quot;&lt;/span&gt;],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;);&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;自定义配置&#34;&gt;&lt;a href=&#34;#自定义配置&#34; class=&#34;headerlink&#34; title=&#34;自定义配置&#34;&gt;&lt;/a&gt;自定义配置&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::injection::&amp;#123;XssDetector, SqlInjectionDetector&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 通过 builder 只装配需要的检测器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(XssDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(SqlInjectionDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;只装配部分检测器&#34;&gt;&lt;a href=&#34;#只装配部分检测器&#34; class=&#34;headerlink&#34; title=&#34;只装配部分检测器&#34;&gt;&lt;/a&gt;只装配部分检测器&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::injection::&amp;#123;XssDetector, SqlInjectionDetector&amp;#125;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;scanner&lt;/span&gt; = Scanner::&lt;span class=&#34;title function_ invoke__&#34;&gt;builder&lt;/span&gt;()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(XssDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;with_detector&lt;/span&gt;(&lt;span class=&#34;type&#34;&gt;Box&lt;/span&gt;::&lt;span class=&#34;title function_ invoke__&#34;&gt;new&lt;/span&gt;(SqlInjectionDetector))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    .&lt;span class=&#34;title function_ invoke__&#34;&gt;build&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;严重度展示&#34;&gt;&lt;a href=&#34;#严重度展示&#34; class=&#34;headerlink&#34; title=&#34;严重度展示&#34;&gt;&lt;/a&gt;严重度展示&lt;/h3&gt;&lt;figure class=&#34;highlight rust&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; security_rust::Severity;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;let&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;r&lt;/span&gt; = &amp;amp;results[&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;println!&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#123;&amp;#125;&amp;quot;&lt;/span&gt;, r.severity);  &lt;span class=&#34;comment&#34;&gt;// CRITICAL | HIGH | MEDIUM | LOW&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;性能&#34;&gt;&lt;a href=&#34;#性能&#34; class=&#34;headerlink&#34; title=&#34;性能&#34;&gt;&lt;/a&gt;性能&lt;/h3&gt;&lt;p&gt;Release 构建下，单检测器扫描 ~100ns/次（RegexSet 预编译），全量 27 检测器扫描约 ~5μs/次。适合高吞吐量场景（API 网关、日志管道）。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;开发&#34;&gt;&lt;a href=&#34;#开发&#34; class=&#34;headerlink&#34; title=&#34;开发&#34;&gt;&lt;/a&gt;开发&lt;/h2&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 构建&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo build --release&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 测试（46 个集成测试）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo &lt;span class=&#34;built_in&#34;&gt;test&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 代码检查&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;cargo clippy -- -D warnings&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;许可&#34;&gt;&lt;a href=&#34;#许可&#34; class=&#34;headerlink&#34; title=&#34;许可&#34;&gt;&lt;/a&gt;许可&lt;/h2&gt;&lt;p&gt;MIT — Copyright (c) 2026 erik &lt;a href=&#34;&amp;#x6d;&amp;#97;&amp;#x69;&amp;#x6c;&amp;#x74;&amp;#x6f;&amp;#58;&amp;#x65;&amp;#114;&amp;#105;&amp;#107;&amp;#x40;&amp;#101;&amp;#114;&amp;#x69;&amp;#107;&amp;#x2e;&amp;#x78;&amp;#x79;&amp;#122;&#34;&gt;&amp;#x65;&amp;#114;&amp;#105;&amp;#107;&amp;#x40;&amp;#101;&amp;#114;&amp;#x69;&amp;#107;&amp;#x2e;&amp;#x78;&amp;#x79;&amp;#122;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;

 &lt;h1 id=&#34;Security-Go-—-Attack-Detection-Library&#34;&gt;&lt;a href=&#34;#Security-Go-—-Attack-Detection-Library&#34; class=&#34;headerlink&#34; title=&#34;Security Go — Attack Detection Library&#34;&gt;&lt;/a&gt;Security Go — Attack Detection Library&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/README-EN.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;An attack detection package written in Go, covering &lt;strong&gt;32 detectors&lt;/strong&gt;, &lt;strong&gt;5 major attack categories&lt;/strong&gt;, and &lt;strong&gt;3 pluggable storage backends&lt;/strong&gt;. Unified interface + registry pattern, a pure detection library that fits any Go HTTP framework.&lt;/p&gt;
&lt;h2 id=&#34;Design&#34;&gt;&lt;a href=&#34;#Design&#34; class=&#34;headerlink&#34; title=&#34;Design&#34;&gt;&lt;/a&gt;Design&lt;/h2&gt;&lt;h3 id=&#34;Core-Principles&#34;&gt;&lt;a href=&#34;#Core-Principles&#34; class=&#34;headerlink&#34; title=&#34;Core Principles&#34;&gt;&lt;/a&gt;Core Principles&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Zero-dependency detection&lt;/strong&gt; — every detector uses only Go’s standard-library &lt;code&gt;regexp&lt;/code&gt;, no external dependencies&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Unified interface&lt;/strong&gt; — each detector implements the &lt;code&gt;Detector&lt;/code&gt; interface (&lt;code&gt;Name()&lt;/code&gt; + &lt;code&gt;Detect()&lt;/code&gt;), managed centrally through the &lt;code&gt;Engine&lt;/code&gt; registry&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Precompiled regexes&lt;/strong&gt; — all patterns are compiled at &lt;code&gt;var&lt;/code&gt; initialization, so runtime overhead is zero&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Configure on demand&lt;/strong&gt; — injection/protocol/data/file detectors work out of the box; the HTTP validators need app-specific configuration&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h3 id=&#34;Design-Architecture&#34;&gt;&lt;a href=&#34;#Design-Architecture&#34; class=&#34;headerlink&#34; title=&#34;Design Architecture&#34;&gt;&lt;/a&gt;Design Architecture&lt;/h3&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                      ┌───────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │        security.Engine         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  ┌─────────────────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │    Detector Registry     │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │   map[string]Detector    │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  └─────────────────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  Detect(name, input)          │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectAll(input)             │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectRequest(*http.Request) │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      └──────────────┬────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌─────────────────┬───────────┴───────────┬─────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                 │                       │                 │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────┐   ┌──────▼──────┐   ┌────────────▼────────┐   ┌───▼───────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  injection  │   │  protocol   │   │        data         │   │     file      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  (10)       │   │  (9)        │   │       (5)           │   │    (3)        │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│             │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xss, sql,  │   │  ssrf, xxe, │   │  deser, csv,        │   │  traversal,   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  command,   │   │  header,    │   │  mail, jwt,         │   │  upload,      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  nosql,     │   │  host,      │   │  proto_poll         │   │  data_leak    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ldap,      │   │  smuggling, │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xpath,     │   │  redirect,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  jndi, ssi, │   │  cors, ws,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  graphql,   │   │  dns_rebind │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ssti       │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────┘   └─────────────┘   └─────────────────────┘   └───────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                                                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌───────────────────────────────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                                                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────────┐                                         ┌──────────▼──────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     httpval     │                                         │       storage       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     (5)         │                                         │  ┌──────────────┐   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                 │                                         │  │   Backend    │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  method, size,  │                                         │  │   interface  │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  type, csrf,    │                                         │  └──┬───┬───┬───┘   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ip_blacklist   │◄───── uses storage.Backend ───────────►│  Memory File Redis │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  (needs config) │                                         │                    │ &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────────┘                                         └────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Data-Flow&#34;&gt;&lt;a href=&#34;#Data-Flow&#34; class=&#34;headerlink&#34; title=&#34;Data Flow&#34;&gt;&lt;/a&gt;Data Flow&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;HTTP Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────┐     ┌─────────────────┐     ┌──────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ collectInputs│────▶│  DetectAll()    │────▶│  []*Result   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ URL, Query,  │     │ per-detector call │     │  aggregated   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Headers,     │     │  Detect(input)  │     │              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Cookies      │     └─────────────────┘     └──────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Severity-Levels&#34;&gt;&lt;a href=&#34;#Severity-Levels&#34; class=&#34;headerlink&#34; title=&#34;Severity Levels&#34;&gt;&lt;/a&gt;Severity Levels&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Level&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;th&gt;Typical Scenario&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityLow&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Low risk&lt;/td&gt;
&lt;td&gt;Invalid HTTP method, Content-Type mismatch&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityMedium&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Medium risk&lt;/td&gt;
&lt;td&gt;CORS misconfiguration, open redirect, GraphQL introspection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityHigh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;High risk&lt;/td&gt;
&lt;td&gt;XSS, SQL injection, SSRF, path traversal&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityCritical&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Critical&lt;/td&gt;
&lt;td&gt;Command injection, JNDI, SSTI, XXE, data leakage&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;What-It-Detects&#34;&gt;&lt;a href=&#34;#What-It-Detects&#34; class=&#34;headerlink&#34; title=&#34;What It Detects&#34;&gt;&lt;/a&gt;What It Detects&lt;/h2&gt;&lt;h3 id=&#34;Injection-Attacks-10&#34;&gt;&lt;a href=&#34;#Injection-Attacks-10&#34; class=&#34;headerlink&#34; title=&#34;Injection Attacks (10)&#34;&gt;&lt;/a&gt;Injection Attacks (10)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Detection Patterns&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XSS&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;script&amp;gt;&lt;/code&gt;, &lt;code&gt;on[a-z]+=&lt;/code&gt; event handlers, &lt;code&gt;javascript:&lt;/code&gt; pseudo-protocol, SVG/CSS injection, &lt;code&gt;eval()&lt;/code&gt;, &lt;code&gt;document.cookie&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SQL Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;UNION SELECT&lt;/code&gt; (including &lt;code&gt;/**/&lt;/code&gt; bypasses), &lt;code&gt;sleep/benchmark/pg_sleep&lt;/code&gt;, boolean blind injection, &lt;code&gt;information_schema&lt;/code&gt; enumeration, &lt;code&gt;xp_cmdshell&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Command Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Backticks, &lt;code&gt;$()&lt;/code&gt;, pipe characters, &lt;code&gt;/dev/tcp&lt;/code&gt;, PHP &lt;code&gt;system/exec/shell_exec&lt;/code&gt;, chained execution &lt;code&gt;&amp;amp;&amp;amp;&lt;/code&gt; &lt;code&gt;;&lt;/code&gt; `\&lt;/td&gt;
&lt;td&gt;\&lt;/td&gt;
&lt;td&gt;`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;NoSQL Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;MongoDB &lt;code&gt;$ne&lt;/code&gt; &lt;code&gt;$gt&lt;/code&gt; &lt;code&gt;$regex&lt;/code&gt; &lt;code&gt;$where&lt;/code&gt; operators, &lt;code&gt;$func&lt;/code&gt;, JSON key injection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;LDAP Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Filter operators `(\&lt;/td&gt;
&lt;td&gt;(&amp;amp;(!&lt;code&gt;,&lt;/code&gt;objectClass=*`, URL-encoding bypasses&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XPATH Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Boolean bypass &lt;code&gt;&amp;#39; or &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt;, &lt;code&gt;string-length()&lt;/code&gt;, &lt;code&gt;count()&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JNDI/Log4Shell&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;$&amp;#123;jndi:ldap://&lt;/code&gt;, &lt;code&gt;$&amp;#123;lower:j&amp;#125;&lt;/code&gt; obfuscation, &lt;code&gt;$&amp;#123;env:&amp;#125;&lt;/code&gt; environment variables, &lt;code&gt;ldap/rmi/dns&lt;/code&gt; protocols&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSI Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!--#exec cmd=&lt;/code&gt;, &lt;code&gt;&amp;lt;!--#include file=&lt;/code&gt;, &lt;code&gt;&amp;lt;!--#echo var=&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GraphQL Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__schema&lt;/code&gt;/&lt;code&gt;__type&lt;/code&gt; introspection, deeply nested DoS (5+ levels), &lt;code&gt;mutation&lt;/code&gt; detection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSTI&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Jinja2 &lt;code&gt;&amp;#123;&amp;#123;&amp;#125;&amp;#125;&lt;/code&gt;, FreeMarker &lt;code&gt;$&amp;#123;&amp;#125;&lt;/code&gt;, ERB &lt;code&gt;&amp;lt;% %&amp;gt;&lt;/code&gt;, Python MRO traversal, &lt;code&gt;config/self&lt;/code&gt; access&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Protocol-and-Request-Attacks-9&#34;&gt;&lt;a href=&#34;#Protocol-and-Request-Attacks-9&#34; class=&#34;headerlink&#34; title=&#34;Protocol and Request Attacks (9)&#34;&gt;&lt;/a&gt;Protocol and Request Attacks (9)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Detection Patterns&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSRF&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Internal IPs (127/10/172.16/192.168), &lt;code&gt;169.254.169.254&lt;/code&gt;, IPv6 loopback, &lt;code&gt;gopher/dict/file/ftp&lt;/code&gt; protocols&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XXE&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!ENTITY SYSTEM/PUBLIC&lt;/code&gt;, parameter entities &lt;code&gt;%entity;&lt;/code&gt;, DOCTYPE declarations&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP Header Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF &lt;code&gt;%0d%0a&lt;/code&gt; / &lt;code&gt;\r\n&lt;/code&gt;, Set-Cookie/Location/Content-Length injection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Host Header Attack&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF Host injection, &lt;code&gt;X-Forwarded-Host&lt;/code&gt;, &lt;code&gt;X-Original-URL&lt;/code&gt; poisoning&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Request Smuggling&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Transfer-Encoding/Content-Length mismatch, double TE headers, &lt;code&gt;\x0b&lt;/code&gt; folded-header obfuscation&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Open Redirect&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;//evil.com&lt;/code&gt; protocol-relative URLs, &lt;code&gt;javascript:/data:&lt;/code&gt; pseudo-protocols&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CORS Bypass&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Origin: null&lt;/code&gt;, &lt;code&gt;Access-Control-Allow-*&lt;/code&gt; header injection&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;WebSocket Hijacking&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Upgrade header injection, null Origin bypass, &lt;code&gt;ws://&lt;/code&gt; URLs&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DNS Rebinding&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Internal IPs in the Host header, localhost, short hostnames with no TLD&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;HTTP-Protocol-Validation-5&#34;&gt;&lt;a href=&#34;#HTTP-Protocol-Validation-5&#34; class=&#34;headerlink&#34; title=&#34;HTTP Protocol Validation (5)&#34;&gt;&lt;/a&gt;HTTP Protocol Validation (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP Method&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Only GET/POST/PUT/DELETE/HEAD/OPTIONS/PATCH are allowed; anything else raises an alert&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Request Body Size&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Exceeding the limit (10MB by default) raises an alert&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Content-Type&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Only the configured MIME type allowlist is accepted&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSRF Origin&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Checks whether the Origin of a cross-origin request matches the Host, with support for an extra allowlist&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;IP Blacklist&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Auto-bans after N attacks within a time window (default 5 per 60s → 15-minute ban), with File/Redis/Memory storage&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Data-and-Deserialization-Attacks-5&#34;&gt;&lt;a href=&#34;#Data-and-Deserialization-Attacks-5&#34; class=&#34;headerlink&#34; title=&#34;Data and Deserialization Attacks (5)&#34;&gt;&lt;/a&gt;Data and Deserialization Attacks (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Detection Patterns&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;PHP Deserialization&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;O:digits:&lt;/code&gt; / &lt;code&gt;C:digits:&lt;/code&gt; serialized objects, &lt;code&gt;unserialize()&lt;/code&gt;, magic methods (&lt;code&gt;__wakeup&lt;/code&gt;/&lt;code&gt;__destruct&lt;/code&gt;)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSV Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;`=cmd\&lt;/td&gt;
&lt;td&gt;&lt;code&gt;,&lt;/code&gt;@SUM(&lt;code&gt;,&lt;/code&gt;+&lt;code&gt;/&lt;/code&gt;-&lt;code&gt;formula prefixes,&lt;/code&gt;HYPERLINK&lt;code&gt;/&lt;/code&gt;DDE`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Email Header Injection&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Bcc/Cc/From/To injection, MIME multipart, boundary parameters&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JWT Attacks&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;alg: none&lt;/code&gt; bypass, &lt;code&gt;kid&lt;/code&gt; path traversal, empty-signature detection (structural decoding analysis)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Prototype Pollution&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__proto__&lt;/code&gt;/&lt;code&gt;constructor&lt;/code&gt; keys, &lt;code&gt;__defineGetter__&lt;/code&gt;/&lt;code&gt;__defineSetter__&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Files-and-Sensitive-Data-3&#34;&gt;&lt;a href=&#34;#Files-and-Sensitive-Data-3&#34; class=&#34;headerlink&#34; title=&#34;Files and Sensitive Data (3)&#34;&gt;&lt;/a&gt;Files and Sensitive Data (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Detector&lt;/th&gt;
&lt;th&gt;Detection Patterns&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Path Traversal&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;../&lt;/code&gt;, &lt;code&gt;..\\&lt;/code&gt;, &lt;code&gt;php://filter&lt;/code&gt;/&lt;code&gt;php://input&lt;/code&gt;, null bytes, URL-encoding bypasses, &lt;code&gt;/etc/passwd&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Malicious Upload&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Extension allowlist (15 types) + content scan for PHP tags &lt;code&gt;&amp;lt;?php&lt;/code&gt;/&lt;code&gt;&amp;lt;?=&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Data Leakage&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Credit card numbers, AWS Access Keys, private keys &lt;code&gt;-----BEGIN&lt;/code&gt;, database connection strings, API tokens, JWT secrets, GitHub PATs&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;Storage-Backends-3&#34;&gt;&lt;a href=&#34;#Storage-Backends-3&#34; class=&#34;headerlink&#34; title=&#34;Storage Backends (3)&#34;&gt;&lt;/a&gt;Storage Backends (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Backend&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Memory&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;sync.Mutex&lt;/code&gt; + map, expired entries swept every 30s&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;File&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;JSON file persistence, flushed on Close&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Redis&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Separate submodule, Pipeline Incr + TTL, requires &lt;code&gt;go-redis/v9&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;Usage&#34;&gt;&lt;a href=&#34;#Usage&#34; class=&#34;headerlink&#34; title=&#34;Usage&#34;&gt;&lt;/a&gt;Usage&lt;/h2&gt;&lt;h3 id=&#34;Installation&#34;&gt;&lt;a href=&#34;#Installation&#34; class=&#34;headerlink&#34; title=&#34;Installation&#34;&gt;&lt;/a&gt;Installation&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;go get github.com/erikwang2013/security-go&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Quick-Start&#34;&gt;&lt;a href=&#34;#Quick-Start&#34; class=&#34;headerlink&#34; title=&#34;Quick Start&#34;&gt;&lt;/a&gt;Quick Start&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;package&lt;/span&gt; main&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;fmt&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go/all&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e) &lt;span class=&#34;comment&#34;&gt;// register all 27 zero-config detectors in one call&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// single detection&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    r := e.Detect(&lt;span class=&#34;string&#34;&gt;&amp;quot;xss&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;lt;script&amp;gt;alert(1)&amp;lt;/script&amp;gt;&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;Detected: %v, Severity: %d\n&amp;quot;&lt;/span&gt;, r.Detected, r.Severity)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// full scan&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, r := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectAll(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#x27; OR &amp;#x27;1&amp;#x27;=&amp;#x27;1&amp;quot;&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;[%s] %s\n&amp;quot;&lt;/span&gt;, r.Name, r.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-Request-Detection&#34;&gt;&lt;a href=&#34;#HTTP-Request-Detection&#34; class=&#34;headerlink&#34; title=&#34;HTTP Request Detection&#34;&gt;&lt;/a&gt;HTTP Request Detection&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;handler&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(w http.ResponseWriter, r *http.Request)&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, result := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectRequest(r) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; result.Detected &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            log.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;Attack detected: [%s] %s&amp;quot;&lt;/span&gt;, result.Name, result.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-Validator-Configuration&#34;&gt;&lt;a href=&#34;#HTTP-Validator-Configuration&#34; class=&#34;headerlink&#34; title=&#34;HTTP Validator Configuration&#34;&gt;&lt;/a&gt;HTTP Validator Configuration&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// method validation&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.Method&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// request body size limit&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewBodySize(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt;)) &lt;span class=&#34;comment&#34;&gt;// 5MB&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// Content-Type allowlist&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewContentType([]&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;application/json&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;application/x-www-form-urlencoded&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// CSRF Origin check&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.CSRFOrigin&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Host: &lt;span class=&#34;string&#34;&gt;&amp;quot;example.com&amp;quot;&lt;/span&gt;, AllowList: []&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;api.example.com&amp;quot;&lt;/span&gt;&amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// IP blacklist (auto-ban: 5 per 60s → 15-minute ban)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mem := storage.NewMemory()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;defer&lt;/span&gt; mem.Close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bl := httpval.NewIPBlacklist(mem)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(bl)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// record when an attack happens&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;blocked, _ := bl.RecordAttack(clientIP)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Custom-Detectors&#34;&gt;&lt;a href=&#34;#Custom-Detectors&#34; class=&#34;headerlink&#34; title=&#34;Custom Detectors&#34;&gt;&lt;/a&gt;Custom Detectors&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;type&lt;/span&gt; MyDetector &lt;span class=&#34;keyword&#34;&gt;struct&lt;/span&gt;&amp;#123;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Name() &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt; &amp;#123; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Detect(input &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;) *security.Result &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &amp;amp;security.Result&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Name: &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt;, Detected: strings.Contains(input, &lt;span class=&#34;string&#34;&gt;&amp;quot;evil&amp;quot;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Severity: security.SeverityHigh, Message: &lt;span class=&#34;string&#34;&gt;&amp;quot;malicious content detected&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;MyDetector&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Related-Docs&#34;&gt;&lt;a href=&#34;#Related-Docs&#34; class=&#34;headerlink&#34; title=&#34;Related Docs&#34;&gt;&lt;/a&gt;Related Docs&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/specs/2026-07-29-attack-detection-design.md&#34;&gt;Design spec&lt;/a&gt; — package structure, core API, detector catalog&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/plans/2026-07-29-attack-detection-plan.md&#34;&gt;Implementation plan&lt;/a&gt; — step-by-step task plan and implementation-variance comparison&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/reports/2026-07-29-code-review-report.md&#34;&gt;Code review report&lt;/a&gt; — bug fixes, test coverage, architecture assessment&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;hr&gt;
&lt;p&gt;Copyright (c) 2026 erik &lt;a href=&#34;&amp;#109;&amp;#x61;&amp;#105;&amp;#x6c;&amp;#116;&amp;#111;&amp;#x3a;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#121;&amp;#x7a;&#34;&gt;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#121;&amp;#x7a;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;

 &lt;h1 id=&#34;Security-Go-—-攻击检测库&#34;&gt;&lt;a href=&#34;#Security-Go-—-攻击检测库&#34; class=&#34;headerlink&#34; title=&#34;Security Go — 攻击检测库&#34;&gt;&lt;/a&gt;Security Go — 攻击检测库&lt;/h1&gt;&lt;p&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/README-EN.md&#34;&gt;English&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;Go 语言编写的攻击检测包，覆盖 &lt;strong&gt;32 个检测器&lt;/strong&gt;、&lt;strong&gt;5 大攻击类别&lt;/strong&gt;、&lt;strong&gt;3 种可插拔存储后端&lt;/strong&gt;。统一接口 + 注册表模式，纯检测库，适配任何 Go HTTP 框架。&lt;/p&gt;
&lt;h2 id=&#34;设计思路&#34;&gt;&lt;a href=&#34;#设计思路&#34; class=&#34;headerlink&#34; title=&#34;设计思路&#34;&gt;&lt;/a&gt;设计思路&lt;/h2&gt;&lt;h3 id=&#34;核心原则&#34;&gt;&lt;a href=&#34;#核心原则&#34; class=&#34;headerlink&#34; title=&#34;核心原则&#34;&gt;&lt;/a&gt;核心原则&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;零依赖检测&lt;/strong&gt; — 所有检测器仅使用 Go 标准库 &lt;code&gt;regexp&lt;/code&gt;，无外部依赖&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;统一接口&lt;/strong&gt; — 每个检测器实现 &lt;code&gt;Detector&lt;/code&gt; 接口（&lt;code&gt;Name()&lt;/code&gt; + &lt;code&gt;Detect()&lt;/code&gt;），通过 &lt;code&gt;Engine&lt;/code&gt; 注册表统一管理&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;预编译正则&lt;/strong&gt; — 所有模式在 &lt;code&gt;var&lt;/code&gt; 初始化时编译，运行时零开销&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;按需配置&lt;/strong&gt; — 注入/协议/数据/文件检测器即插即用；HTTP 校验器需应用自定义配置&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h3 id=&#34;设计架构&#34;&gt;&lt;a href=&#34;#设计架构&#34; class=&#34;headerlink&#34; title=&#34;设计架构&#34;&gt;&lt;/a&gt;设计架构&lt;/h3&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;                      ┌───────────────────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │        security.Engine         │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  ┌─────────────────────────┐  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │    Detector Registry     │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  │   map[string]Detector    │  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  └─────────────────────────┘  │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  Detect(name, input)          │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectAll(input)             │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      │  DetectRequest(*http.Request) │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                      └──────────────┬────────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌─────────────────┬───────────┴───────────┬─────────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                 │                       │                 │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────┐   ┌──────▼──────┐   ┌────────────▼────────┐   ┌───▼───────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  injection  │   │  protocol   │   │        data         │   │     file      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   (10 个)   │   │   (9 个)    │   │       (5 个)        │   │    (3 个)     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│             │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xss, sql,  │   │  ssrf, xxe, │   │  deser, csv,        │   │  traversal,   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  command,   │   │  header,    │   │  mail, jwt,         │   │  upload,      │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  nosql,     │   │  host,      │   │  proto_poll         │   │  data_leak    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ldap,      │   │  smuggling, │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  xpath,     │   │  redirect,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  jndi, ssi, │   │  cors, ws,  │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  graphql,   │   │  dns_rebind │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ssti       │   │             │   │                     │   │               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────┘   └─────────────┘   └─────────────────────┘   └───────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;                                                                       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       ┌───────────────────────────────────────────────────────────────┤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;       │                                                               │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────▼──────────┐                                         ┌──────────▼──────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     httpval     │                                         │       storage       │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│     (5 个)      │                                         │  ┌──────────────┐   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│                 │                                         │  │   Backend    │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  method, size,  │                                         │  │   interface  │   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  type, csrf,    │                                         │  └──┬───┬───┬───┘   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  ip_blacklist   │◄────── 使用 storage.Backend ──────────►│  Memory File Redis │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│  (需配置参数)    │                                         │                    │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─────────────────┘                                         └────────────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;数据流&#34;&gt;&lt;a href=&#34;#数据流&#34; class=&#34;headerlink&#34; title=&#34;数据流&#34;&gt;&lt;/a&gt;数据流&lt;/h3&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;HTTP Request&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;     ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──────────────┐     ┌─────────────────┐     ┌──────────────┐&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ collectInputs│────▶│  DetectAll()    │────▶│  []*Result   │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ URL, Query,  │     │  逐个检测器调用   │     │  聚合结果     │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Headers,     │     │  Detect(input)  │     │              │&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│ Cookies      │     └─────────────────┘     └──────────────┘&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└──────────────┘&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;严重程度分级&#34;&gt;&lt;a href=&#34;#严重程度分级&#34; class=&#34;headerlink&#34; title=&#34;严重程度分级&#34;&gt;&lt;/a&gt;严重程度分级&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;级别&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;典型场景&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityLow&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;低风险&lt;/td&gt;
&lt;td&gt;非法 HTTP 方法、Content-Type 不匹配&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityMedium&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;中风险&lt;/td&gt;
&lt;td&gt;CORS 配置问题、开放重定向、GraphQL 内省&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityHigh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;高风险&lt;/td&gt;
&lt;td&gt;XSS、SQL 注入、SSRF、路径遍历&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SeverityCritical&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;严重&lt;/td&gt;
&lt;td&gt;命令注入、JNDI、SSTI、XXE、数据泄露&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;实现功能&#34;&gt;&lt;a href=&#34;#实现功能&#34; class=&#34;headerlink&#34; title=&#34;实现功能&#34;&gt;&lt;/a&gt;实现功能&lt;/h2&gt;&lt;h3 id=&#34;注入类攻击-10&#34;&gt;&lt;a href=&#34;#注入类攻击-10&#34; class=&#34;headerlink&#34; title=&#34;注入类攻击 (10)&#34;&gt;&lt;/a&gt;注入类攻击 (10)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XSS&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;script&amp;gt;&lt;/code&gt;、&lt;code&gt;on[a-z]+=&lt;/code&gt; 事件处理器、&lt;code&gt;javascript:&lt;/code&gt; 伪协议、SVG/CSS 注入、&lt;code&gt;eval()&lt;/code&gt;、&lt;code&gt;document.cookie&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;UNION SELECT&lt;/code&gt;（含 &lt;code&gt;/**/&lt;/code&gt; 绕过）、&lt;code&gt;sleep/benchmark/pg_sleep&lt;/code&gt;、布尔盲注、&lt;code&gt;information_schema&lt;/code&gt; 枚举、&lt;code&gt;xp_cmdshell&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;命令注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;反引号、&lt;code&gt;$()&lt;/code&gt;、管道符、&lt;code&gt;/dev/tcp&lt;/code&gt;、PHP &lt;code&gt;system/exec/shell_exec&lt;/code&gt;、链式执行 &lt;code&gt;&amp;amp;&amp;amp;&lt;/code&gt; &lt;code&gt;;&lt;/code&gt; `\&lt;/td&gt;
&lt;td&gt;\&lt;/td&gt;
&lt;td&gt;`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;NoSQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;MongoDB &lt;code&gt;$ne&lt;/code&gt; &lt;code&gt;$gt&lt;/code&gt; &lt;code&gt;$regex&lt;/code&gt; &lt;code&gt;$where&lt;/code&gt; 操作符、&lt;code&gt;$func&lt;/code&gt;、JSON 键注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;LDAP 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;过滤操作符 `(\&lt;/td&gt;
&lt;td&gt;(&amp;amp;(!&lt;code&gt;、&lt;/code&gt;objectClass=*`、URL 编码绕过&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XPATH 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;布尔绕过 &lt;code&gt;&amp;#39; or &amp;#39;1&amp;#39;=&amp;#39;1&lt;/code&gt;、&lt;code&gt;string-length()&lt;/code&gt;、&lt;code&gt;count()&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JNDI/Log4Shell&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;$&amp;#123;jndi:ldap://&lt;/code&gt;、&lt;code&gt;$&amp;#123;lower:j&amp;#125;&lt;/code&gt; 混淆、&lt;code&gt;$&amp;#123;env:&amp;#125;&lt;/code&gt; 环境变量、&lt;code&gt;ldap/rmi/dns&lt;/code&gt; 协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSI 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!--#exec cmd=&lt;/code&gt;、&lt;code&gt;&amp;lt;!--#include file=&lt;/code&gt;、&lt;code&gt;&amp;lt;!--#echo var=&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;GraphQL 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__schema&lt;/code&gt;/&lt;code&gt;__type&lt;/code&gt; 内省、深度嵌套 DoS（5层+）、&lt;code&gt;mutation&lt;/code&gt; 检测&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSTI&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Jinja2 &lt;code&gt;&amp;#123;&amp;#123;&amp;#125;&amp;#125;&lt;/code&gt;、FreeMarker &lt;code&gt;$&amp;#123;&amp;#125;&lt;/code&gt;、ERB &lt;code&gt;&amp;lt;% %&amp;gt;&lt;/code&gt;、Python MRO 遍历、&lt;code&gt;config/self&lt;/code&gt; 访问&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;协议与请求攻击-9&#34;&gt;&lt;a href=&#34;#协议与请求攻击-9&#34; class=&#34;headerlink&#34; title=&#34;协议与请求攻击 (9)&#34;&gt;&lt;/a&gt;协议与请求攻击 (9)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;SSRF&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;内网 IP（127/10/172.16/192.168）、&lt;code&gt;169.254.169.254&lt;/code&gt;、IPv6 loopback、&lt;code&gt;gopher/dict/file/ftp&lt;/code&gt; 协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;XXE&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;&amp;lt;!ENTITY SYSTEM/PUBLIC&lt;/code&gt;、参数实体 &lt;code&gt;%entity;&lt;/code&gt;、DOCTYPE 声明&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP 头注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF &lt;code&gt;%0d%0a&lt;/code&gt; / &lt;code&gt;\r\n&lt;/code&gt;、Set-Cookie/Location/Content-Length 注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Host 头攻击&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;CRLF Host 注入、&lt;code&gt;X-Forwarded-Host&lt;/code&gt;、&lt;code&gt;X-Original-URL&lt;/code&gt; 投毒&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;请求走私&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Transfer-Encoding/Content-Length 不一致、双重 TE 头、&lt;code&gt;\x0b&lt;/code&gt; 折叠头混淆&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;开放重定向&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;//evil.com&lt;/code&gt; 协议相对 URL、&lt;code&gt;javascript:/data:&lt;/code&gt; 伪协议&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CORS 绕过&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Origin: null&lt;/code&gt;、&lt;code&gt;Access-Control-Allow-*&lt;/code&gt; 头注入&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;WebSocket 劫持&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Upgrade 头注入、null Origin 绕过、&lt;code&gt;ws://&lt;/code&gt; URL&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;DNS 重绑定&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Host 头内网 IP、localhost、无 TLD 短主机名&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;HTTP-协议层校验-5&#34;&gt;&lt;a href=&#34;#HTTP-协议层校验-5&#34; class=&#34;headerlink&#34; title=&#34;HTTP 协议层校验 (5)&#34;&gt;&lt;/a&gt;HTTP 协议层校验 (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;HTTP 方法&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;仅允许 GET/POST/PUT/DELETE/HEAD/OPTIONS/PATCH，其他返回告警&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;请求体大小&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;超过上限（默认 10MB）触发告警&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Content-Type&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;仅允许配置的 MIME 类型白名单&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSRF Origin&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;检测跨域请求 Origin 与 Host 是否匹配，支持额外白名单&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;IP 黑名单&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;窗口时间 N 次攻击后自动封禁（默认 5次/60s→封禁15分钟），支持 File/Redis/Memory 存储&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;数据与序列化攻击-5&#34;&gt;&lt;a href=&#34;#数据与序列化攻击-5&#34; class=&#34;headerlink&#34; title=&#34;数据与序列化攻击 (5)&#34;&gt;&lt;/a&gt;数据与序列化攻击 (5)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;PHP 反序列化&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;O:数字:&lt;/code&gt; / &lt;code&gt;C:数字:&lt;/code&gt; 序列化对象、&lt;code&gt;unserialize()&lt;/code&gt;、魔术方法（&lt;code&gt;__wakeup&lt;/code&gt;/&lt;code&gt;__destruct&lt;/code&gt;）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;CSV 注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;`=cmd\&lt;/td&gt;
&lt;td&gt;&lt;code&gt;、&lt;/code&gt;@SUM(&lt;code&gt;、&lt;/code&gt;+&lt;code&gt;/&lt;/code&gt;-&lt;code&gt;公式前缀、&lt;/code&gt;HYPERLINK&lt;code&gt;/&lt;/code&gt;DDE`&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;邮件头注入&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;Bcc/Cc/From/To 注入、MIME multipart、boundary 参数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;JWT 攻击&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;alg: none&lt;/code&gt; 绕过、&lt;code&gt;kid&lt;/code&gt; 路径遍历、空签名检测（结构解码分析）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;原型污染&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;__proto__&lt;/code&gt;/&lt;code&gt;constructor&lt;/code&gt; 键、&lt;code&gt;__defineGetter__&lt;/code&gt;/&lt;code&gt;__defineSetter__&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;文件与敏感数据-3&#34;&gt;&lt;a href=&#34;#文件与敏感数据-3&#34; class=&#34;headerlink&#34; title=&#34;文件与敏感数据 (3)&#34;&gt;&lt;/a&gt;文件与敏感数据 (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;检测器&lt;/th&gt;
&lt;th&gt;检测模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;路径遍历&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;../&lt;/code&gt;、&lt;code&gt;..\\&lt;/code&gt;、&lt;code&gt;php://filter&lt;/code&gt;/&lt;code&gt;php://input&lt;/code&gt;、null 字节、URL 编码绕过、&lt;code&gt;/etc/passwd&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;恶意上传&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;扩展名白名单（15种）+ PHP 标签 &lt;code&gt;&amp;lt;?php&lt;/code&gt;/&lt;code&gt;&amp;lt;?=&lt;/code&gt; 内容扫描&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;数据泄露&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;信用卡号、AWS Access Key、私钥 &lt;code&gt;-----BEGIN&lt;/code&gt;、数据库连接串、API Token、JWT Secret、GitHub PAT&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;存储后端-3&#34;&gt;&lt;a href=&#34;#存储后端-3&#34; class=&#34;headerlink&#34; title=&#34;存储后端 (3)&#34;&gt;&lt;/a&gt;存储后端 (3)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;后端&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Memory&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;sync.Mutex&lt;/code&gt; + map，30s 自动清理过期条目&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;File&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;JSON 文件持久化，Close 时 flush&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Redis&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;独立子模块，Pipeline Incr + TTL，需 &lt;code&gt;go-redis/v9&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;使用说明&#34;&gt;&lt;a href=&#34;#使用说明&#34; class=&#34;headerlink&#34; title=&#34;使用说明&#34;&gt;&lt;/a&gt;使用说明&lt;/h2&gt;&lt;h3 id=&#34;安装&#34;&gt;&lt;a href=&#34;#安装&#34; class=&#34;headerlink&#34; title=&#34;安装&#34;&gt;&lt;/a&gt;安装&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;go get github.com/erikwang2013/security-go&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;package&lt;/span&gt; main&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; (&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;fmt&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;github.com/erikwang2013/security-go/all&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e) &lt;span class=&#34;comment&#34;&gt;// 一键注册 27 个零配置检测器&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 单个检测&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    r := e.Detect(&lt;span class=&#34;string&#34;&gt;&amp;quot;xss&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;lt;script&amp;gt;alert(1)&amp;lt;/script&amp;gt;&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;检测到: %v, 严重程度: %d\n&amp;quot;&lt;/span&gt;, r.Detected, r.Severity)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;comment&#34;&gt;// 全量检测&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, r := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectAll(&lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;#x27; OR &amp;#x27;1&amp;#x27;=&amp;#x27;1&amp;quot;&lt;/span&gt;) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        fmt.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;[%s] %s\n&amp;quot;&lt;/span&gt;, r.Name, r.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-请求检测&#34;&gt;&lt;a href=&#34;#HTTP-请求检测&#34; class=&#34;headerlink&#34; title=&#34;HTTP 请求检测&#34;&gt;&lt;/a&gt;HTTP 请求检测&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;handler&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;(w http.ResponseWriter, r *http.Request)&lt;/span&gt;&lt;/span&gt; &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    e := security.NewEngine()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    all.RegisterAll(e)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;for&lt;/span&gt; _, result := &lt;span class=&#34;keyword&#34;&gt;range&lt;/span&gt; e.DetectRequest(r) &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; result.Detected &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            log.Printf(&lt;span class=&#34;string&#34;&gt;&amp;quot;攻击检测: [%s] %s&amp;quot;&lt;/span&gt;, result.Name, result.Message)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;HTTP-校验器配置&#34;&gt;&lt;a href=&#34;#HTTP-校验器配置&#34; class=&#34;headerlink&#34; title=&#34;HTTP 校验器配置&#34;&gt;&lt;/a&gt;HTTP 校验器配置&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 方法校验&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.Method&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 请求体大小限制&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewBodySize(&lt;span class=&#34;number&#34;&gt;5&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt; * &lt;span class=&#34;number&#34;&gt;1024&lt;/span&gt;)) &lt;span class=&#34;comment&#34;&gt;// 5MB&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// Content-Type 白名单&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(httpval.NewContentType([]&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;application/json&amp;quot;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;quot;application/x-www-form-urlencoded&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// CSRF Origin 检查&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;httpval.CSRFOrigin&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    Host: &lt;span class=&#34;string&#34;&gt;&amp;quot;example.com&amp;quot;&lt;/span&gt;, AllowList: []&lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;&amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;quot;api.example.com&amp;quot;&lt;/span&gt;&amp;#125;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// IP 黑名单（自动封禁：5次/60s → 封禁15分钟）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mem := storage.NewMemory()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;defer&lt;/span&gt; mem.Close()&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;bl := httpval.NewIPBlacklist(mem)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(bl)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;// 攻击发生时记录&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;blocked, _ := bl.RecordAttack(clientIP)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;自定义检测器&#34;&gt;&lt;a href=&#34;#自定义检测器&#34; class=&#34;headerlink&#34; title=&#34;自定义检测器&#34;&gt;&lt;/a&gt;自定义检测器&lt;/h3&gt;&lt;figure class=&#34;highlight go&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;type&lt;/span&gt; MyDetector &lt;span class=&#34;keyword&#34;&gt;struct&lt;/span&gt;&amp;#123;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Name() &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt; &amp;#123; &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;function&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;func&lt;/span&gt; &lt;span class=&#34;params&#34;&gt;(d *MyDetector)&lt;/span&gt;&lt;/span&gt; Detect(input &lt;span class=&#34;type&#34;&gt;string&lt;/span&gt;) *security.Result &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; &amp;amp;security.Result&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Name: &lt;span class=&#34;string&#34;&gt;&amp;quot;my_detector&amp;quot;&lt;/span&gt;, Detected: strings.Contains(input, &lt;span class=&#34;string&#34;&gt;&amp;quot;evil&amp;quot;&lt;/span&gt;),&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        Severity: security.SeverityHigh, Message: &lt;span class=&#34;string&#34;&gt;&amp;quot;检测到恶意内容&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;e.Register(&amp;amp;MyDetector&amp;#123;&amp;#125;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;相关文档&#34;&gt;&lt;a href=&#34;#相关文档&#34; class=&#34;headerlink&#34; title=&#34;相关文档&#34;&gt;&lt;/a&gt;相关文档&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/specs/2026-07-29-attack-detection-design.md&#34;&gt;设计规范&lt;/a&gt; — 包结构、核心 API、检测器目录&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/plans/2026-07-29-attack-detection-plan.md&#34;&gt;实施计划&lt;/a&gt; — 分步任务计划与实施偏差对照&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/security-go/blob/main/docs/superpowers/reports/2026-07-29-code-review-report.md&#34;&gt;代码审查报告&lt;/a&gt; — Bug 修复、测试覆盖、架构评估&lt;/li&gt;
&lt;/ul&gt;
