&lt;h2 id=&#34;支持的框架&#34;&gt;&lt;a href=&#34;#支持的框架&#34; class=&#34;headerlink&#34; title=&#34;支持的框架&#34;&gt;&lt;/a&gt;支持的框架&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;框架&lt;/th&gt;
&lt;th&gt;检测方式&lt;/th&gt;
&lt;th&gt;协程&lt;/th&gt;
&lt;th&gt;集成方式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Plain PHP&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;默认回退&lt;/td&gt;
&lt;td&gt;Fiber&lt;/td&gt;
&lt;td&gt;Kernel 实例化&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Laravel&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Illuminate\Foundation\Application&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Octane Swoole&lt;/td&gt;
&lt;td&gt;ServiceProvider + Facade + artisan&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Webman&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Workerman\Worker&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Swoole/Fiber&lt;/td&gt;
&lt;td&gt;config/plugin 自动发现&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Hyperf&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;Hyperf\Framework\ApplicationFactory&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Swoole 原生&lt;/td&gt;
&lt;td&gt;ConfigProvider + DI&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;ThinkPHP&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;think\App&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;think-swoole&lt;/td&gt;
&lt;td&gt;services.php + 单例&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Yii2&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;yii\base\Application&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;swoole-yii2&lt;/td&gt;
&lt;td&gt;Bootstrap + 组件&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;p&gt;检测优先级：&lt;code&gt;Laravel → Webman → Hyperf → ThinkPHP → Yii2 → Plain PHP&lt;/code&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h2&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;composer require erikwang2013/industrial-protocols-kernel erikwang2013/industrial-protocols-modbus&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;figure class=&#34;highlight php&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;?php&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;require&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;vendor/autoload.php&amp;#x27;&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;Erikwang2013&lt;/span&gt;\&lt;span class=&#34;title&#34;&gt;IndustrialProtocols&lt;/span&gt;\&lt;span class=&#34;title&#34;&gt;Kernel&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;use&lt;/span&gt; &lt;span class=&#34;title&#34;&gt;Erikwang2013&lt;/span&gt;\&lt;span class=&#34;title&#34;&gt;IndustrialProtocols&lt;/span&gt;\&lt;span class=&#34;title&#34;&gt;Modbus&lt;/span&gt;\&lt;span class=&#34;title&#34;&gt;ModbusProtocol&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt; = &lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;Kernel&lt;/span&gt;([&lt;span class=&#34;string&#34;&gt;&amp;#x27;config_path&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;keyword&#34;&gt;__DIR__&lt;/span&gt; . &lt;span class=&#34;string&#34;&gt;&amp;#x27;/industrial-protocols.php&amp;#x27;&lt;/span&gt;]);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;getProtocolRegistry&lt;/span&gt;()-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;register&lt;/span&gt;(&lt;span class=&#34;keyword&#34;&gt;new&lt;/span&gt; &lt;span class=&#34;title class_&#34;&gt;ModbusProtocol&lt;/span&gt;());&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;boot&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$conn&lt;/span&gt; = &lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;getConnectionManager&lt;/span&gt;()-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;connect&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;plc-001&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$result&lt;/span&gt; = &lt;span class=&#34;variable&#34;&gt;$conn&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;read&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;40001&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;variable&#34;&gt;$result&lt;/span&gt;[&lt;span class=&#34;string&#34;&gt;&amp;#x27;40001&amp;#x27;&lt;/span&gt;];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$conn&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;write&lt;/span&gt;([&lt;span class=&#34;string&#34;&gt;&amp;#x27;40001&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;]);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$health&lt;/span&gt; = &lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;getConnectionManager&lt;/span&gt;()-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;health&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;&amp;#x27;plc-001&amp;#x27;&lt;/span&gt;);&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;&lt;span class=&#34;subst&#34;&gt;&amp;#123;$health-&amp;gt;state-&amp;gt;value&amp;#125;&lt;/span&gt;, &lt;span class=&#34;subst&#34;&gt;&amp;#123;$health-&amp;gt;latencyMs&amp;#125;&lt;/span&gt;ms&amp;quot;&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;variable&#34;&gt;$kernel&lt;/span&gt;-&amp;gt;&lt;span class=&#34;title function_ invoke__&#34;&gt;shutdown&lt;/span&gt;();&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;配置参考&#34;&gt;&lt;a href=&#34;#配置参考&#34; class=&#34;headerlink&#34; title=&#34;配置参考&#34;&gt;&lt;/a&gt;配置参考&lt;/h2&gt;&lt;figure class=&#34;highlight php&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;meta&#34;&gt;&amp;lt;?php&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;return&lt;/span&gt; [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;devices&amp;#x27;&lt;/span&gt; =&amp;gt; [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        &lt;span class=&#34;string&#34;&gt;&amp;#x27;plc-001&amp;#x27;&lt;/span&gt; =&amp;gt; [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;protocol&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;modbus&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;variant&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;tcp&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;host&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;192.168.1.10&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;port&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;502&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;            &lt;span class=&#34;string&#34;&gt;&amp;#x27;unit_id&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;, &lt;span class=&#34;string&#34;&gt;&amp;#x27;timeout&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;3000&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        ],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;gateway&amp;#x27;&lt;/span&gt; =&amp;gt; [&lt;span class=&#34;string&#34;&gt;&amp;#x27;rules&amp;#x27;&lt;/span&gt; =&amp;gt; []],&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;health_check_interval&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;default_retry_max&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;#x27;default_retry_backoff&amp;#x27;&lt;/span&gt; =&amp;gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;exponential&amp;#x27;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;];&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;hr&gt;
&lt;h2 id=&#34;文档&#34;&gt;&lt;a href=&#34;#文档&#34; class=&#34;headerlink&#34; title=&#34;文档&#34;&gt;&lt;/a&gt;文档&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/industrial-protocols/tree/main/docs/protocols.md&#34;&gt;协议 API 参考&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/industrial-protocols/tree/main/docs/framework-integration.md&#34;&gt;框架集成指南&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/industrial-protocols/tree/main/docs/gateway.md&#34;&gt;网关引擎指南&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/industrial-protocols/tree/main/docs/security.md&#34;&gt;安全指南&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/erikwang2013/industrial-protocols/tree/main/docs/vendors.md&#34;&gt;厂商适配参考&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;系统要求&#34;&gt;&lt;a href=&#34;#系统要求&#34; class=&#34;headerlink&#34; title=&#34;系统要求&#34;&gt;&lt;/a&gt;系统要求&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;PHP &amp;gt;= 8.1&lt;/li&gt;
&lt;li&gt;Composer&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;License&#34;&gt;&lt;a href=&#34;#License&#34; class=&#34;headerlink&#34; title=&#34;License&#34;&gt;&lt;/a&gt;License&lt;/h2&gt;&lt;p&gt;MIT — Copyright (c) 2026 erik &lt;a href=&#34;&amp;#109;&amp;#97;&amp;#x69;&amp;#108;&amp;#116;&amp;#x6f;&amp;#x3a;&amp;#101;&amp;#x72;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#121;&amp;#x7a;&#34;&gt;&amp;#101;&amp;#x72;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#114;&amp;#105;&amp;#x6b;&amp;#46;&amp;#120;&amp;#121;&amp;#x7a;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;

 &lt;h1 id=&#34;Global-Game-Platform&#34;&gt;&lt;a href=&#34;#Global-Game-Platform&#34; class=&#34;headerlink&#34; title=&#34;Global Game Platform&#34;&gt;&lt;/a&gt;Global Game Platform&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;Copyright (c) 2026 erik &lt;a href=&#34;&amp;#109;&amp;#97;&amp;#x69;&amp;#x6c;&amp;#x74;&amp;#111;&amp;#58;&amp;#101;&amp;#x72;&amp;#105;&amp;#x6b;&amp;#64;&amp;#x65;&amp;#x72;&amp;#x69;&amp;#107;&amp;#x2e;&amp;#x78;&amp;#x79;&amp;#122;&#34;&gt;&amp;#101;&amp;#x72;&amp;#105;&amp;#x6b;&amp;#64;&amp;#x65;&amp;#x72;&amp;#x69;&amp;#107;&amp;#x2e;&amp;#x78;&amp;#x79;&amp;#122;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;A universal, internationalized game aggregation platform. After registering, users top up on the platform and exchange that balance for game coins; they use the coins to play games and earn more coins, and coins can be converted back into wallet balance for withdrawal. The admin panel provides complete game management, withdrawal review, user management and payment management. Multi-language switching (English/Chinese) is supported.&lt;/p&gt;
&lt;h2 id=&#34;Version-strategy&#34;&gt;&lt;a href=&#34;#Version-strategy&#34; class=&#34;headerlink&#34; title=&#34;Version strategy&#34;&gt;&lt;/a&gt;Version strategy&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Version&lt;/th&gt;
&lt;th&gt;Goal&lt;/th&gt;
&lt;th&gt;Status&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;Basic (MVP)&lt;/td&gt;
&lt;td&gt;Get the core loop working: register → top up → exchange → play → withdraw → review&lt;/td&gt;
&lt;td&gt;Done&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Standard&lt;/td&gt;
&lt;td&gt;Production-ready: global payments, third-party game SDKs, basic risk control, three front ends&lt;/td&gt;
&lt;td&gt;Planned&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Full&lt;/td&gt;
&lt;td&gt;The complete version: multi-language, leaderboards, coupons, full risk control, every feature&lt;/td&gt;
&lt;td&gt;Planned&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h4 id=&#34;Download&#34;&gt;&lt;a href=&#34;#Download&#34; class=&#34;headerlink&#34; title=&#34;Download&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://github.com/erikwang2013/game-platform-php-lite&#34;&gt;Download&lt;/a&gt;&lt;/h4&gt;&lt;h2 id=&#34;Tech-stack&#34;&gt;&lt;a href=&#34;#Tech-stack&#34; class=&#34;headerlink&#34; title=&#34;Tech stack&#34;&gt;&lt;/a&gt;Tech stack&lt;/h2&gt;&lt;h3 id=&#34;Backend&#34;&gt;&lt;a href=&#34;#Backend&#34; class=&#34;headerlink&#34; title=&#34;Backend&#34;&gt;&lt;/a&gt;Backend&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;PHP 8.3+, webman v2 (workerman/webman)&lt;/li&gt;
&lt;li&gt;MySQL 8.0+ (table prefix &lt;code&gt;erik_&lt;/code&gt;, BIGINT non-auto-increment primary keys)&lt;/li&gt;
&lt;li&gt;Redis (session / cache / rate limiting)&lt;/li&gt;
&lt;li&gt;Elasticsearch (full-text search)&lt;/li&gt;
&lt;li&gt;JWT authentication + RBAC permissions&lt;/li&gt;
&lt;li&gt;Data encryption: AES-256-CBC at the API transport layer + AES-128-ECB at the database storage layer&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Frontend&#34;&gt;&lt;a href=&#34;#Frontend&#34; class=&#34;headerlink&#34; title=&#34;Frontend&#34;&gt;&lt;/a&gt;Frontend&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;Flutter 3.x (Web PC style)&lt;/li&gt;
&lt;li&gt;HarmonyOS ArkTS (mobile)&lt;/li&gt;
&lt;li&gt;Responsive layout (Phone / Tablet / Desktop)&lt;/li&gt;
&lt;li&gt;Internationalization (i18n): English / Simplified Chinese switching&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;Core-components&#34;&gt;&lt;a href=&#34;#Core-components&#34; class=&#34;headerlink&#34; title=&#34;Core components&#34;&gt;&lt;/a&gt;Core components&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/snowflake-php&lt;/code&gt; — globally unique BIGINT ID generation&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/hashids&lt;/code&gt; — ID encryption/decryption at the API layer&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/jwt-webman&lt;/code&gt; — JWT authentication&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/encryption&lt;/code&gt; — encrypt/decrypt sensitive API data&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/encryptable&lt;/code&gt; — encrypt/decrypt sensitive database fields&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/webman-scout&lt;/code&gt; — Elasticsearch sync and query&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/season&lt;/code&gt; — country flags&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/security-php&lt;/code&gt; — security tooling detection&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/poster-php&lt;/code&gt; — random verification for sensitive operations&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Project-structure&#34;&gt;&lt;a href=&#34;#Project-structure&#34; class=&#34;headerlink&#34; title=&#34;Project structure&#34;&gt;&lt;/a&gt;Project structure&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;game-platform-php/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── admin/                     # Admin panel (webman v2, port 8787)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/admin/controller/  #   admin-side controllers&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/middleware/        #   middleware (Cors/Security/RateLimit/Auth/Permission)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── config/                #   configuration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── database/migrations/   #   SQL migration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── apps/flutter/          #   Flutter Web PC admin panel&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── service/                   # Client-facing service (webman v2, port 8788)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/api/v1/controller/ #   client API controllers&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/middleware/        #   middleware&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── config/                #   configuration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── common/                    # Shared layer (PSR-4 autoload)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── model/                 #   data models (25)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── middleware/            #   shared middleware (UserAuth)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── service/               #   shared services (4)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── flutter/platform/      # Flutter Web PC client user platform&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                      # Project documentation&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── ARCHITECTURE.md        #   architecture doc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── ARCHITECTURE-DESIGN.md #   architecture design doc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── FEATURES.md            #   features doc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── FEATURE-DESIGN.md      #   feature design doc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── API.md                 #   API doc&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── admin/docs/superpowers/    # Development standards and plans&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── specs/                 #   design specs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    └── plans/                 #   implementation plans&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;Quick-start&#34;&gt;&lt;a href=&#34;#Quick-start&#34; class=&#34;headerlink&#34; title=&#34;Quick start&#34;&gt;&lt;/a&gt;Quick start&lt;/h2&gt;&lt;h3 id=&#34;Requirements&#34;&gt;&lt;a href=&#34;#Requirements&#34; class=&#34;headerlink&#34; title=&#34;Requirements&#34;&gt;&lt;/a&gt;Requirements&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;PHP 8.3+&lt;/li&gt;
&lt;li&gt;MySQL 8.0+&lt;/li&gt;
&lt;li&gt;Redis 6.0+&lt;/li&gt;
&lt;li&gt;Composer 2.x&lt;/li&gt;
&lt;li&gt;Flutter SDK 3.x (frontend)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;1-Initialize-the-database&#34;&gt;&lt;a href=&#34;#1-Initialize-the-database&#34; class=&#34;headerlink&#34; title=&#34;1. Initialize the database&#34;&gt;&lt;/a&gt;1. Initialize the database&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Create the database&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -e &lt;span class=&#34;string&#34;&gt;&amp;quot;CREATE DATABASE IF NOT EXISTS game_platform CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Run the migrations (in numeric order)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_22_000003_platform_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_22_000004_i18n_tables.sql&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;2-Start-the-backend&#34;&gt;&lt;a href=&#34;#2-Start-the-backend&#34; class=&#34;headerlink&#34; title=&#34;2. Start the backend&#34;&gt;&lt;/a&gt;2. Start the backend&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Admin panel (port 8787)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; admin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# edit the database connection settings&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;php start.php start -d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Client-facing service (port 8788)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# edit the database connection settings&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;php start.php start -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;3-Start-the-frontend&#34;&gt;&lt;a href=&#34;#3-Start-the-frontend&#34; class=&#34;headerlink&#34; title=&#34;3. Start the frontend&#34;&gt;&lt;/a&gt;3. Start the frontend&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Admin panel (Flutter Web PC)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; admin/apps/flutter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Client user platform (Flutter Web PC)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; apps/flutter/platform&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;4-Verify&#34;&gt;&lt;a href=&#34;#4-Verify&#34; class=&#34;headerlink&#34; title=&#34;4. Verify&#34;&gt;&lt;/a&gt;4. Verify&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Test the admin panel&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl http://localhost:8787/health&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Test the client-facing service&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl http://localhost:8788/health&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# Test user registration&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl -X POST http://localhost:8788/api/auth/register \&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  -H &lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type: application/json&amp;quot;&lt;/span&gt; \&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  -d &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#123;&amp;quot;username&amp;quot;:&amp;quot;testuser&amp;quot;,&amp;quot;password&amp;quot;:&amp;quot;123456&amp;quot;&amp;#125;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;Security-features&#34;&gt;&lt;a href=&#34;#Security-features&#34; class=&#34;headerlink&#34; title=&#34;Security features&#34;&gt;&lt;/a&gt;Security features&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;18 layers of defense in depth&lt;/strong&gt;: XSS/SQL injection/CSRF/path traversal/command injection detection and blocking&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;HTTP method whitelist&lt;/strong&gt;: only GET/POST/PUT/DELETE/OPTIONS/HEAD allowed&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;JWT authentication&lt;/strong&gt;: access_token 2h + refresh_token 14d, with a limit on concurrent sessions&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;RBAC permissions&lt;/strong&gt;: method.path granularity permission control, cached in Redis for 60s&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Click captcha&lt;/strong&gt;: mandatory human verification on login/registration&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Password re-confirmation&lt;/strong&gt;: sensitive operations require the password to be entered again&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Data encryption&lt;/strong&gt;: AES-256-CBC at the transport layer + AES-128-ECB at the storage layer&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;ID encryption&lt;/strong&gt;: Snowflake generation + Hashids encoding, so IDs cannot be reverse-engineered from outside&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Wallet optimistic locking&lt;/strong&gt;: prevents concurrent debits and duplicate credits&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Operation auditing&lt;/strong&gt;: full operation logs, with automatic detection of 8 source platforms&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Rate limiting&lt;/strong&gt;: Redis sliding window, made atomic with Lua&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;CSP header&lt;/strong&gt;: Content-Security-Policy to prevent XSS&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Account security&lt;/strong&gt;: 5 consecutive failed logins locks the account for 15 minutes&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;Business-model&#34;&gt;&lt;a href=&#34;#Business-model&#34; class=&#34;headerlink&#34; title=&#34;Business model&#34;&gt;&lt;/a&gt;Business model&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;Fiat currency (USD/CNY/EUR...)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  Top up (Stripe/PayPal/Alipay/WeChat Pay)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Platform coin (unified, precision decimal(18,4))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  Exchange (includes the exchange rate + platform spread)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Game coin (independent per game, independent exchange rate)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  Play games to earn/spend&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;Platform coin ← convert back → withdrawal (reviewed/automatic)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h1 id=&#34;全球游戏聚合平台-Global-Game-Platform&#34;&gt;&lt;a href=&#34;#全球游戏聚合平台-Global-Game-Platform&#34; class=&#34;headerlink&#34; title=&#34;全球游戏聚合平台 (Global Game Platform)&#34;&gt;&lt;/a&gt;全球游戏聚合平台 (Global Game Platform)&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;Copyright (c) 2026 erik &lt;a href=&#34;&amp;#x6d;&amp;#97;&amp;#105;&amp;#x6c;&amp;#116;&amp;#111;&amp;#x3a;&amp;#x65;&amp;#114;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#101;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#x2e;&amp;#x78;&amp;#121;&amp;#x7a;&#34;&gt;&amp;#x65;&amp;#114;&amp;#x69;&amp;#x6b;&amp;#x40;&amp;#101;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#x2e;&amp;#x78;&amp;#121;&amp;#x7a;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;全球通用、国际化的游戏聚合平台。用户注册后在平台充值兑换游戏币，用游戏币玩游戏、赚取游戏币，游戏币可转回钱包提现。后台提供完整的游戏管理、提现审核、用户管理和支付管理功能。支持多语言切换（英文/中文）。&lt;/p&gt;
&lt;h2 id=&#34;版本策略&#34;&gt;&lt;a href=&#34;#版本策略&#34; class=&#34;headerlink&#34; title=&#34;版本策略&#34;&gt;&lt;/a&gt;版本策略&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;版本&lt;/th&gt;
&lt;th&gt;目标&lt;/th&gt;
&lt;th&gt;状态&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;基础版 (MVP)&lt;/td&gt;
&lt;td&gt;跑通核心闭环：注册→充值→兑换→游戏→提现→审核&lt;/td&gt;
&lt;td&gt;已完成&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;标准版&lt;/td&gt;
&lt;td&gt;生产可用：全球化支付、第三方游戏SDK、基础风控、三端前端&lt;/td&gt;
&lt;td&gt;规划中&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;完整版&lt;/td&gt;
&lt;td&gt;完全体：多语言、排行榜、优惠券、完整风控、全量功能&lt;/td&gt;
&lt;td&gt;规划中&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h4 id=&#34;下载&#34;&gt;&lt;a href=&#34;#下载&#34; class=&#34;headerlink&#34; title=&#34;下载&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://github.com/erikwang2013/game-platform-php-lite&#34;&gt;下载&lt;/a&gt;&lt;/h4&gt;&lt;h2 id=&#34;技术栈&#34;&gt;&lt;a href=&#34;#技术栈&#34; class=&#34;headerlink&#34; title=&#34;技术栈&#34;&gt;&lt;/a&gt;技术栈&lt;/h2&gt;&lt;h3 id=&#34;后端&#34;&gt;&lt;a href=&#34;#后端&#34; class=&#34;headerlink&#34; title=&#34;后端&#34;&gt;&lt;/a&gt;后端&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;PHP 8.3+, webman v2 (workerman/webman)&lt;/li&gt;
&lt;li&gt;MySQL 8.0+ (表前缀 &lt;code&gt;erik_&lt;/code&gt;，BIGINT 非自增主键)&lt;/li&gt;
&lt;li&gt;Redis (Session / 缓存 / 限流)&lt;/li&gt;
&lt;li&gt;Elasticsearch (全文检索)&lt;/li&gt;
&lt;li&gt;JWT 认证 + RBAC 权限控制&lt;/li&gt;
&lt;li&gt;数据加密：API 传输层 AES-256-CBC + 数据库存储层 AES-128-ECB&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;前端&#34;&gt;&lt;a href=&#34;#前端&#34; class=&#34;headerlink&#34; title=&#34;前端&#34;&gt;&lt;/a&gt;前端&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;Flutter 3.x (Web PC 风格)&lt;/li&gt;
&lt;li&gt;HarmonyOS ArkTS (移动端)&lt;/li&gt;
&lt;li&gt;响应式布局 (Phone / Tablet / Desktop)&lt;/li&gt;
&lt;li&gt;国际化 (i18n)：英文 / 简体中文切换&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;核心组件&#34;&gt;&lt;a href=&#34;#核心组件&#34; class=&#34;headerlink&#34; title=&#34;核心组件&#34;&gt;&lt;/a&gt;核心组件&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/snowflake-php&lt;/code&gt; — 全局唯一 BIGINT ID 生成&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/hashids&lt;/code&gt; — API 层 ID 加解密&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/jwt-webman&lt;/code&gt; — JWT 认证&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/encryption&lt;/code&gt; — API 敏感数据加解密&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/encryptable&lt;/code&gt; — 数据库敏感字段加解密&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/webman-scout&lt;/code&gt; — Elasticsearch 同步与查询&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/season&lt;/code&gt; — 国家旗帜&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/security-php&lt;/code&gt; — 安全工具检测&lt;/li&gt;
&lt;li&gt;&lt;code&gt;erikwang2013/poster-php&lt;/code&gt; — 敏感操作随机验证&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;项目结构&#34;&gt;&lt;a href=&#34;#项目结构&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;game-platform-php/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── admin/                     # 管理后台 (webman v2, 端口 8787)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/admin/controller/  #   管理端控制器&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/middleware/        #   中间件 (Cors/Security/RateLimit/Auth/Permission)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── config/                #   配置文件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── database/migrations/   #   SQL 迁移文件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── apps/flutter/          #   Flutter Web PC 管理后台&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── service/                   # C端业务端 (webman v2, 端口 8788)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/api/v1/controller/ #   C端 API 控制器&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/middleware/        #   中间件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── config/                #   配置文件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── common/                    # 共享层 (PSR-4 autoload)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── model/                 #   数据模型 (25个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── middleware/            #   共享中间件 (UserAuth)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── service/               #   共享服务 (4个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── flutter/platform/      # Flutter Web PC C端用户平台&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                      # 项目文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── ARCHITECTURE.md        #   架构文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── ARCHITECTURE-DESIGN.md #   架构设计文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── FEATURES.md            #   功能文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── FEATURE-DESIGN.md      #   功能设计文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── API.md                 #   接口文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── admin/docs/superpowers/    # 开发规范与计划&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── specs/                 #   设计规范&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    └── plans/                 #   实现计划&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h2&gt;&lt;h3 id=&#34;环境要求&#34;&gt;&lt;a href=&#34;#环境要求&#34; class=&#34;headerlink&#34; title=&#34;环境要求&#34;&gt;&lt;/a&gt;环境要求&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;PHP 8.3+&lt;/li&gt;
&lt;li&gt;MySQL 8.0+&lt;/li&gt;
&lt;li&gt;Redis 6.0+&lt;/li&gt;
&lt;li&gt;Composer 2.x&lt;/li&gt;
&lt;li&gt;Flutter SDK 3.x (前端)&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;1-数据库初始化&#34;&gt;&lt;a href=&#34;#1-数据库初始化&#34; class=&#34;headerlink&#34; title=&#34;1. 数据库初始化&#34;&gt;&lt;/a&gt;1. 数据库初始化&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 创建数据库&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -e &lt;span class=&#34;string&#34;&gt;&amp;quot;CREATE DATABASE IF NOT EXISTS game_platform CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 执行迁移（按编号顺序）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_22_000003_platform_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root game_platform &amp;lt; admin/database/migrations/2026_05_22_000004_i18n_tables.sql&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;2-后端启动&#34;&gt;&lt;a href=&#34;#2-后端启动&#34; class=&#34;headerlink&#34; title=&#34;2. 后端启动&#34;&gt;&lt;/a&gt;2. 后端启动&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 管理后台 (端口 8787)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; admin&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# 编辑数据库连接信息&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;php start.php start -d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# C端业务端 (端口 8788)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; service&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;   &lt;span class=&#34;comment&#34;&gt;# 编辑数据库连接信息&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;php start.php start -d&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;3-前端启动&#34;&gt;&lt;a href=&#34;#3-前端启动&#34; class=&#34;headerlink&#34; title=&#34;3. 前端启动&#34;&gt;&lt;/a&gt;3. 前端启动&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 管理后台 (Flutter Web PC)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; admin/apps/flutter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# C端用户平台 (Flutter Web PC)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; apps/flutter/platform&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;4-验证&#34;&gt;&lt;a href=&#34;#4-验证&#34; class=&#34;headerlink&#34; title=&#34;4. 验证&#34;&gt;&lt;/a&gt;4. 验证&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 测试管理后台&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl http://localhost:8787/health&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 测试C端业务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl http://localhost:8788/health&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 测试用户注册&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;curl -X POST http://localhost:8788/api/auth/register \&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  -H &lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type: application/json&amp;quot;&lt;/span&gt; \&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  -d &lt;span class=&#34;string&#34;&gt;&amp;#x27;&amp;#123;&amp;quot;username&amp;quot;:&amp;quot;testuser&amp;quot;,&amp;quot;password&amp;quot;:&amp;quot;123456&amp;quot;&amp;#125;&amp;#x27;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;安全特性&#34;&gt;&lt;a href=&#34;#安全特性&#34; class=&#34;headerlink&#34; title=&#34;安全特性&#34;&gt;&lt;/a&gt;安全特性&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;18 层纵深防御&lt;/strong&gt;：XSS/SQL注入/CSRF/路径遍历/命令注入检测拦截&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;HTTP 方法白名单&lt;/strong&gt;：仅允许 GET/POST/PUT/DELETE/OPTIONS/HEAD&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;JWT 认证&lt;/strong&gt;：access_token 2h + refresh_token 14d，并发会话限制&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;RBAC 权限&lt;/strong&gt;：method.path 粒度权限控制，Redis 60s 缓存&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;点击验证码&lt;/strong&gt;：登录/注册强制人机验证&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;密码二次确认&lt;/strong&gt;：敏感操作需输入密码确认&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;数据加密&lt;/strong&gt;：传输层 AES-256-CBC + 存储层 AES-128-ECB&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;ID 加密&lt;/strong&gt;：Snowflake 生成 + Hashids 编码，外部不可逆推&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;钱包乐观锁&lt;/strong&gt;：防止并发扣款/重复到账&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;操作审计&lt;/strong&gt;：全量操作日志，8 平台来源端自动检测&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;限流&lt;/strong&gt;：Redis 滑动窗口，Lua 原子化&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;CSP 头&lt;/strong&gt;：Content-Security-Policy 防 XSS&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;账号安全&lt;/strong&gt;：连续5次登录失败锁定15分钟&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;业务模型&#34;&gt;&lt;a href=&#34;#业务模型&#34; class=&#34;headerlink&#34; title=&#34;业务模型&#34;&gt;&lt;/a&gt;业务模型&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;法币 (USD/CNY/EUR...)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  充值(Stripe/PayPal/支付宝/微信)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;平台币 (统一，精度 decimal(18,4))&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  兑换（含汇率 + 平台抽成差价）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;游戏币 (每种游戏独立，独立汇率)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  │  玩游戏赚/花&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  ▼&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;平台币 ← 兑回 → 提现（审核/自动）&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

 &lt;h1 id=&#34;Property-Management-Platform&#34;&gt;&lt;a href=&#34;#Property-Management-Platform&#34; class=&#34;headerlink&#34; title=&#34;Property Management Platform&#34;&gt;&lt;/a&gt;Property Management Platform&lt;/h1&gt;&lt;blockquote&gt;
&lt;p&gt;Copyright (c) 2026 erik &lt;a href=&#34;&amp;#x6d;&amp;#97;&amp;#x69;&amp;#108;&amp;#116;&amp;#x6f;&amp;#x3a;&amp;#101;&amp;#114;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#46;&amp;#x78;&amp;#x79;&amp;#122;&#34;&gt;&amp;#101;&amp;#114;&amp;#105;&amp;#x6b;&amp;#x40;&amp;#x65;&amp;#x72;&amp;#x69;&amp;#x6b;&amp;#46;&amp;#x78;&amp;#x79;&amp;#122;&lt;/a&gt; — &lt;a href=&#34;https://erik.xyz&#34;&gt;https://erik.xyz&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;A full-stack property management system covering 15 business modules, from community management and fee collection to repair and maintenance, parking and access control, security, and cleaning. The admin side (admin) and the owner side (service) are deployed separately, and the front end covers Flutter Web (PC admin console style) plus a HarmonyOS mobile app.&lt;/p&gt;
&lt;h2 id=&#34;Project-Structure&#34;&gt;&lt;a href=&#34;#Project-Structure&#34; class=&#34;headerlink&#34; title=&#34;Project Structure&#34;&gt;&lt;/a&gt;Project Structure&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;property-management-platform/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── admin/                         # admin-side webman v2 project&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── admin/controller/      # admin controllers&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── api/v1/controller/     # public API controllers&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── common/                # shared utility classes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── middleware/            # middleware (auth/permission/rate limiting/security)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── model/                 # data models (Eloquent ORM)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── queue/                 # queued jobs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── process/               # process management&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── flutter/               # admin console Flutter Web (PC style)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── harmonyos/             # admin console HarmonyOS app&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── config/                    # configuration files (with Chinese comments)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── database/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── migrations/            # SQL migration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── backup/                # database backup scripts&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── resource/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── translations/          # i18n language files (zh_CN / en)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── docs/                      # admin-side docs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── tests/                     # unit tests&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── public/                    # web entry point&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── service/                       # owner-side webman v2 project&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── app/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── api/v1/controller/     # owner-side API controllers&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── common/                # shared utility classes&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── middleware/            # middleware&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── model/                 # data models&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── process/               # process management&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── config/                    # configuration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── resource/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── translations/          # i18n language files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── database/migrations/       # SQL migration files&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── flutter/                   # owner-side Flutter Web (PC style)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── harmonyos/                 # owner-side HarmonyOS app&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── docs/                          # project docs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── ARCHITECTURE.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── ARCHITECTURE_DESIGN.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── API.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    ├── FEATURES.md&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    └── FEATURE_DESIGN.md&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
