&lt;h3 id=&#34;Client-endpoints-requires-the-API-Version-header&#34;&gt;&lt;a href=&#34;#Client-endpoints-requires-the-API-Version-header&#34; class=&#34;headerlink&#34; title=&#34;Client endpoints (requires the API-Version header)&#34;&gt;&lt;/a&gt;Client endpoints (requires the API-Version header)&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Method&lt;/th&gt;
&lt;th&gt;Path&lt;/th&gt;
&lt;th&gt;Description&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/product&lt;/code&gt;&lt;/td&gt;
