&lt;/div&gt;
&lt;span id=&#34;more&#34;&gt;&lt;/span&gt;
&lt;h4 id=&#34;下载&#34;&gt;&lt;a href=&#34;#下载&#34; class=&#34;headerlink&#34; title=&#34;下载&#34;&gt;&lt;/a&gt;&lt;a href=&#34;https://github.com/erikwang2013/erp-php-lite&#34;&gt;下载&lt;/a&gt;&lt;/h4&gt;&lt;h2 id=&#34;ERP-模块&#34;&gt;&lt;a href=&#34;#ERP-模块&#34; class=&#34;headerlink&#34; title=&#34;ERP 模块&#34;&gt;&lt;/a&gt;ERP 模块&lt;/h2&gt;&lt;p&gt;各业务模块间的数据流转：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;采购收货 → 自动入库（移动加权平均成本核算） → 自动生成应付&lt;/li&gt;
&lt;li&gt;销售发货 → 自动出库 → 自动生成应收&lt;/li&gt;
&lt;li&gt;收付款 → 核销应收应付 → 更新日记账&lt;/li&gt;
&lt;li&gt;凭证审核 → 自动更新总账(科目汇总) + 明细账(逐笔记录)&lt;/li&gt;
&lt;li&gt;资产负债表 → 自动汇总总账期末余额生成&lt;/li&gt;
&lt;li&gt;现金流量表 → 自动汇总现金银行日记账生成（经营/投资/筹资三分类）&lt;/li&gt;
&lt;li&gt;审批工作流 → 业务单据提交审批 → 多节点流转 → 审批结果回调业务模块&lt;/li&gt;
&lt;li&gt;消息通知 → 审批/预警/系统事件触发 → 实时推送 → 用户标记已读&lt;/li&gt;
&lt;li&gt;MRP → 基于销售订单+BOM → 计算物料需求 → 生成采购建议/生产建议&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;技术栈&#34;&gt;&lt;a href=&#34;#技术栈&#34; class=&#34;headerlink&#34; title=&#34;技术栈&#34;&gt;&lt;/a&gt;技术栈&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;层&lt;/th&gt;
&lt;th&gt;技术&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;后端框架&lt;/td&gt;
&lt;td&gt;webman v2 (workerman)&lt;/td&gt;
&lt;td&gt;超高性能 PHP 常驻进程框架&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;PHP 版本&lt;/td&gt;
&lt;td&gt;8.3+&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;数据库&lt;/td&gt;
&lt;td&gt;MySQL 8.0+&lt;/td&gt;
&lt;td&gt;表前缀 &lt;code&gt;erik_&lt;/code&gt;，BIGINT 非自增主键&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;搜索引擎&lt;/td&gt;
&lt;td&gt;Elasticsearch&lt;/td&gt;
&lt;td&gt;通过 &lt;code&gt;webman-scout&lt;/code&gt; 同步与查询&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;管理端前端&lt;/td&gt;
&lt;td&gt;Flutter 3.x&lt;/td&gt;
&lt;td&gt;Web 端为 PC 管理后台风格（&lt;code&gt;apps/flutter/&lt;/code&gt;）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;移动端&lt;/td&gt;
&lt;td&gt;HarmonyOS ArkTS&lt;/td&gt;
&lt;td&gt;鸿蒙原生客户端（&lt;code&gt;apps/harmonyos/&lt;/code&gt;），支持手机/平板/2in1&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;核心依赖&#34;&gt;&lt;a href=&#34;#核心依赖&#34; class=&#34;headerlink&#34; title=&#34;核心依赖&#34;&gt;&lt;/a&gt;核心依赖&lt;/h2&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;包&lt;/th&gt;
&lt;th&gt;用途&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/snowflake-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Snowflake 算法生成全局唯一 BIGINT 主键&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/hashids&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;API 层 ID 加解密，隐藏真实数据库 ID&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/jwt-webman&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JWT 认证令牌签发与校验&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/encryption&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;接口传输层敏感数据加解密&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/encryptable&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数据库存储层敏感字段自动加解密&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/webman-scout&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Elasticsearch 数据同步与全文检索&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/season&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;国家旗帜数据&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/poster-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;点击验证码生成与校验 + 海报生成&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;erikwang2013/security-php&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;安全工具检查&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;phpoffice/phpspreadsheet&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Excel 导出&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;barryvdh/laravel-dompdf&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;PDF 导出（基于 Dompdf）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;hg/apidoc&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;API 文档自动生成&lt;/td&gt;
&lt;td&gt;注解式接口文档，管理端/客户端分组&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h2 id=&#34;国际化&#34;&gt;&lt;a href=&#34;#国际化&#34; class=&#34;headerlink&#34; title=&#34;国际化&#34;&gt;&lt;/a&gt;国际化&lt;/h2&gt;&lt;p&gt;国际化 | Accept-Language 头自动检测 | 中文/English 双语支持&lt;/p&gt;
&lt;h2 id=&#34;项目结构&#34;&gt;&lt;a href=&#34;#项目结构&#34; class=&#34;headerlink&#34; title=&#34;项目结构&#34;&gt;&lt;/a&gt;项目结构&lt;/h2&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;34&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;35&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;36&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;37&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;38&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;39&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;40&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;41&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;42&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;open-erp/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── app/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── admin/controller/       # 系统管理控制器 (14 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── api/v1/controller/      # 客户端 API（版本由 API-Version 请求头控制）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── controller/             # 业务模块控制器 (70 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── product/            # 商品/分类/品牌/仓库/库位/供应商/客户 (7 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── purchase/           # 采购申请/订单/收货/退货/结算 (5 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── sales/              # 销售报价/订单/发货/退货/结算 (5 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── inventory/          # 库存/流水/调拨/盘点/预警 (5 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── finance/            # 应收应付/凭证/收付款/日记账/总账/明细账/报表/资产/税务/多币种/预算/成本利润中心 (20 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── crm/                # 商机/跟进/漏斗/联系人/公海池/合同/报价/营销/工单/分析 (10 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── workflow/           # 工作流定义/审批提交/批准/拒绝/撤回 (2 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── notification/       # 通知列表/已读/未读计数 (1 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── project/            # 项目/任务/工时记录 (3 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── hr/                 # 部门/员工/职位/考勤/请假/薪资 (5 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── manufacturing/      # BOM/生产订单/工艺路线/工作站/MRP (5 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── report/             # 报表模板/数据集/执行/定时调度 (2 个)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── service/                # 业务逻辑层&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── inventory/          # 出入库 + 移动加权平均成本核算&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   ├── finance/            # 应收应付自动生成 + 核销&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   │   └── notification/       # 通知发送服务&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── model/                  # 121 个 Eloquent 模型（多模块共用）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── middleware/             # 9 个中间件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── common/                 # Hashids/Snowflake/Encryption 服务&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── queue/                  # 队列任务&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── apps/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── flutter/                # Flutter 跨平台（Web PC + iOS/Android/macOS/Windows/Linux）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── harmonyos/              # HarmonyOS 原生客户端&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── config/                     # 配置文件（含中文注释）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── plugin/hg/apidoc/        # API 文档配置&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── database/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   ├── migrations/             # SQL 迁移文件（18 个，122 张表）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── backup/                 # 备份/恢复脚本&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── docs/                       # 架构、设计、安全、API 文档&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── tests/                      # PHPUnit 测试（11 个测试文件，90 个测试方法，168 条断言）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── resource/&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│   └── translations/           # 翻译文件 (zh_CN, en)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│       ├── zh_CN/              # 中文翻译 (127 键)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;│       └── en/                 # English translations (127 keys)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── public/                     # 公共入口&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;├── runtime/                    # 运行时文件&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└── vendor/                     # Composer 依赖&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;环境要求&#34;&gt;&lt;a href=&#34;#环境要求&#34; class=&#34;headerlink&#34; title=&#34;环境要求&#34;&gt;&lt;/a&gt;环境要求&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;PHP &amp;gt;= 8.3&lt;/li&gt;
&lt;li&gt;Composer 2.x&lt;/li&gt;
&lt;li&gt;MySQL &amp;gt;= 8.0&lt;/li&gt;
&lt;li&gt;Flutter &amp;gt;= 3.41（仅前端开发需要）&lt;/li&gt;
&lt;li&gt;Elasticsearch &amp;gt;= 7.x（可选，搜索功能需要）&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;快速开始&#34;&gt;&lt;a href=&#34;#快速开始&#34; class=&#34;headerlink&#34; title=&#34;快速开始&#34;&gt;&lt;/a&gt;快速开始&lt;/h2&gt;&lt;h3 id=&#34;1-安装依赖&#34;&gt;&lt;a href=&#34;#1-安装依赖&#34; class=&#34;headerlink&#34; title=&#34;1. 安装依赖&#34;&gt;&lt;/a&gt;1. 安装依赖&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;composer install&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;2-配置环境变量&#34;&gt;&lt;a href=&#34;#2-配置环境变量&#34; class=&#34;headerlink&#34; title=&#34;2. 配置环境变量&#34;&gt;&lt;/a&gt;2. 配置环境变量&lt;/h3&gt;&lt;p&gt;复制并修改环境变量（可选，不配置则使用 &lt;code&gt;config/*.php&lt;/code&gt; 中的默认值）:&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.example .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;关键配置项：&lt;/p&gt;
&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;环境变量&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;th&gt;默认值&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;JWT_SECRET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;JWT 签名密钥&lt;/td&gt;
&lt;td&gt;&lt;code&gt;open-admin-jwt-secret-change-in-production&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;HASHIDS_SALT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Hashids 盐值&lt;/td&gt;
&lt;td&gt;&lt;code&gt;open-admin-hashids-salt-2026&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;ENCRYPTION_KEY&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;API 加密密钥&lt;/td&gt;
&lt;td&gt;32 字节默认值&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SNOWFLAKE_DATACENTER_ID&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;数据中心 ID (0-31)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SNOWFLAKE_WORKER_ID&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;工作节点 ID (0-31)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;1&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;SCOUT_HOSTS&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;ES 地址&lt;/td&gt;
&lt;td&gt;&lt;code&gt;http://localhost:9200&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;生产环境务必修改所有密钥为随机字符串。&lt;/strong&gt;&lt;/p&gt;
&lt;h3 id=&#34;3-初始化数据库&#34;&gt;&lt;a href=&#34;#3-初始化数据库&#34; class=&#34;headerlink&#34; title=&#34;3. 初始化数据库&#34;&gt;&lt;/a&gt;3. 初始化数据库&lt;/h3&gt;&lt;p&gt;按顺序执行 &lt;code&gt;database/migrations/&lt;/code&gt; 下的 SQL 文件：&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 建表&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -p &amp;lt; database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 播种权限数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;mysql -u root -p &amp;lt; database/migrations/2026_05_20_000001_seed_permissions.sql&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;4-启动服务&#34;&gt;&lt;a href=&#34;#4-启动服务&#34; class=&#34;headerlink&#34; title=&#34;4. 启动服务&#34;&gt;&lt;/a&gt;4. 启动服务&lt;/h3&gt;&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;php start.php start&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;默认监听 &lt;code&gt;http://0.0.0.0:8787&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;5-启动前端（可选）&#34;&gt;&lt;a href=&#34;#5-启动前端（可选）&#34; class=&#34;headerlink&#34; title=&#34;5. 启动前端（可选）&#34;&gt;&lt;/a&gt;5. 启动前端（可选）&lt;/h3&gt;&lt;p&gt;&lt;strong&gt;Flutter 管理后台（Web 端）:&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cd&lt;/span&gt; apps/flutter&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter pub get&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;flutter run -d chrome    &lt;span class=&#34;comment&#34;&gt;# Web 端（PC 管理后台风格）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;strong&gt;HarmonyOS 客户端（手机端）:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;使用 DevEco Studio 打开 &lt;code&gt;apps/harmonyos/&lt;/code&gt; 目录，连接真机或模拟器运行。&lt;/p&gt;
&lt;h3 id=&#34;6-Docker-Compose-一键部署（推荐生产环境）&#34;&gt;&lt;a href=&#34;#6-Docker-Compose-一键部署（推荐生产环境）&#34; class=&#34;headerlink&#34; title=&#34;6. Docker Compose 一键部署（推荐生产环境）&#34;&gt;&lt;/a&gt;6. Docker Compose 一键部署（推荐生产环境）&lt;/h3&gt;&lt;p&gt;项目提供完整的 Docker 编排方案，包含 5 个服务：Nginx、PHP (webman app)、MySQL、Redis、Elasticsearch。&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 1. 配置 Docker 环境变量&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;cp&lt;/span&gt; .env.docker .&lt;span class=&#34;built_in&#34;&gt;env&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 2. 启动所有服务&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose up -d&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 3. 初始化数据库（进入 app 容器执行）&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose &lt;span class=&#34;built_in&#34;&gt;exec&lt;/span&gt; app mysql -h mysql -u root -p &amp;lt; database/migrations/2026_05_16_000000_init_tables.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;docker-compose &lt;span class=&#34;built_in&#34;&gt;exec&lt;/span&gt; app mysql -h mysql -u root -p &amp;lt; database/migrations/2026_05_20_000001_seed_permissions.sql&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 4. 访问&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# http://localhost:8787  (webman)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# http://localhost:8080  (Nginx 反向代理)&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;Dockerfile&lt;/code&gt;: PHP 8.3 + OPcache + Composer，基于 &lt;code&gt;php:8.3-cli&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;docker-compose.yml&lt;/code&gt;: 5 个服务编排，网络隔离，数据卷持久化&lt;/li&gt;
&lt;li&gt;&lt;code&gt;.env.docker&lt;/code&gt;: Docker 环境专用环境变量&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;数据库规范&#34;&gt;&lt;a href=&#34;#数据库规范&#34; class=&#34;headerlink&#34; title=&#34;数据库规范&#34;&gt;&lt;/a&gt;数据库规范&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;表前缀&lt;/strong&gt;: &lt;code&gt;erik_&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;主键&lt;/strong&gt;: 所有表主键均为 &lt;code&gt;id BIGINT UNSIGNED NOT NULL&lt;/code&gt;，&lt;strong&gt;禁用 AUTO_INCREMENT&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;ID 生成&lt;/strong&gt;: 主键 ID 由应用层 &lt;code&gt;SnowflakeService::generate()&lt;/code&gt; 生成，分布式唯一&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;必备字段&lt;/strong&gt;: 每张表必须包含 &lt;code&gt;id&lt;/code&gt;, &lt;code&gt;created_at&lt;/code&gt;, &lt;code&gt;updated_at&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;软删除&lt;/strong&gt;: 需要软删除的表添加 &lt;code&gt;deleted_at DATETIME DEFAULT NULL&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;敏感字段&lt;/strong&gt;: 手机号、邮箱、身份证号等使用 &lt;code&gt;encryptable&lt;/code&gt; 插件自动加解密，数据库字段使用 &lt;code&gt;VARCHAR(500)&lt;/code&gt; 存储密文&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;API-规范&#34;&gt;&lt;a href=&#34;#API-规范&#34; class=&#34;headerlink&#34; title=&#34;API 规范&#34;&gt;&lt;/a&gt;API 规范&lt;/h2&gt;&lt;h3 id=&#34;API-文档&#34;&gt;&lt;a href=&#34;#API-文档&#34; class=&#34;headerlink&#34; title=&#34;API 文档&#34;&gt;&lt;/a&gt;API 文档&lt;/h3&gt;&lt;p&gt;项目使用 hg/apidoc 自动生成接口文档，访问 &lt;code&gt;/apidoc&lt;/code&gt; 查看。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;管理端接口 (Admin)：25 个模块分组，含完整请求参数和响应结构&lt;/li&gt;
&lt;li&gt;客户端接口 (Service API)：认证/验证码/商品 3 个分组&lt;/li&gt;
&lt;li&gt;所有接口标注了 JWT 认证、API 版本、国际化等全局请求头&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;统一响应格式&#34;&gt;&lt;a href=&#34;#统一响应格式&#34; class=&#34;headerlink&#34; title=&#34;统一响应格式&#34;&gt;&lt;/a&gt;统一响应格式&lt;/h3&gt;&lt;figure class=&#34;highlight json&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;code&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;message&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;success&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;,&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;attr&#34;&gt;&amp;quot;data&amp;quot;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;业务错误码&#34;&gt;&lt;a href=&#34;#业务错误码&#34; class=&#34;headerlink&#34; title=&#34;业务错误码&#34;&gt;&lt;/a&gt;业务错误码&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;错误码&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;成功&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;400&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;请求参数错误&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;401&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;未登录（Token 无效或过期）&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;403&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;无权限 / 安全拦截&lt;/td&gt;
&lt;td&gt;RBAC 鉴权失败 / SecurityFilter 攻击检测&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;404&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;资源不存在&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;422&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;参数验证失败&lt;/td&gt;
&lt;td&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;413&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;请求体过大&lt;/td&gt;
&lt;td&gt;SecurityFilter 触发，超过 10MB&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;405&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;请求方法不允许&lt;/td&gt;
&lt;td&gt;SecurityFilter 触发，仅允许 GET/POST/PUT/DELETE/OPTIONS/HEAD&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;415&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;不支持的媒体类型&lt;/td&gt;
&lt;td&gt;SecurityFilter 触发，Content-Type 非 JSON&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;429&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;请求过于频繁&lt;/td&gt;
&lt;td&gt;RateLimit 触发 / 账号锁定（5次登录失败锁定15分钟）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;500&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;服务器内部错误&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;国际化-1&#34;&gt;&lt;a href=&#34;#国际化-1&#34; class=&#34;headerlink&#34; title=&#34;国际化&#34;&gt;&lt;/a&gt;国际化&lt;/h3&gt;&lt;p&gt;请求头 &lt;code&gt;Accept-Language&lt;/code&gt; 自动切换语言（zh-CN → 中文, en → English），默认中文。&lt;/p&gt;
&lt;h3 id=&#34;ID-处理&#34;&gt;&lt;a href=&#34;#ID-处理&#34; class=&#34;headerlink&#34; title=&#34;ID 处理&#34;&gt;&lt;/a&gt;ID 处理&lt;/h3&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;请求/响应中的 ID&lt;/strong&gt;: 使用 hashids 加密为字符串，不暴露真实数据库 ID&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;接口路径&lt;/strong&gt;: &lt;code&gt;GET /admin/user/&amp;#123;hashid&amp;#125;&lt;/code&gt; — 路径中的 &lt;code&gt;&amp;#123;id&amp;#125;&lt;/code&gt; 为 hashid 字符串&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;数据库存储&lt;/strong&gt;: BIGINT 原值，由 snowflake 生成&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;API-版本&#34;&gt;&lt;a href=&#34;#API-版本&#34; class=&#34;headerlink&#34; title=&#34;API 版本&#34;&gt;&lt;/a&gt;API 版本&lt;/h3&gt;&lt;p&gt;API 版本通过请求头控制，&lt;strong&gt;不在 URL 中体现&lt;/strong&gt;：&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;API-Version&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;v1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;未携带版本号时默认使用 &lt;code&gt;v1&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;不支持的版本返回 &lt;code&gt;400 Bad Request&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;新增版本时只需创建 &lt;code&gt;app/api/&amp;#123;version&amp;#125;/controller/&lt;/code&gt; 目录，中间件注册新版本即可&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;限流&#34;&gt;&lt;a href=&#34;#限流&#34; class=&#34;headerlink&#34; title=&#34;限流&#34;&gt;&lt;/a&gt;限流&lt;/h3&gt;&lt;p&gt;基于 Redis 滑动窗口算法，默认 60 次/分钟/IP/路由。敏感接口更严格：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;登录：10 次/分钟&lt;/li&gt;
&lt;li&gt;注册：5 次/分钟&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;响应头包含 &lt;code&gt;X-RateLimit-Limit&lt;/code&gt;、&lt;code&gt;X-RateLimit-Remaining&lt;/code&gt;、&lt;code&gt;X-RateLimit-Reset&lt;/code&gt;。超限返回 429 并附带 &lt;code&gt;Retry-After&lt;/code&gt;。&lt;/p&gt;
&lt;h3 id=&#34;中间件架构&#34;&gt;&lt;a href=&#34;#中间件架构&#34; class=&#34;headerlink&#34; title=&#34;中间件架构&#34;&gt;&lt;/a&gt;中间件架构&lt;/h3&gt;&lt;p&gt;全局中间件对所有请求生效，按序执行：&lt;/p&gt;
&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;Locale（Accept-Language 自动检测，设置语言环境）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → Cors（跨域预处理 + 响应头）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → SecurityFilter（HTTP方法限制/请求体大小/Content-Type校验/XSS/SQL注入/路径遍历/命令注入/CSRF 攻击拦截）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → RateLimit（Redis 滑动窗口限流 + 账号锁定：5次登录失败锁定15分钟）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → ApiVersion（API 版本校验，/api 路由组）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → AdminAuth（JWT 认证 + 黑名单，/admin 路由组）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → AdminPermission（RBAC 鉴权，/admin 路由组）&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  → OperationLog（POST/PUT/DELETE 自动记录，含来源端检测，/admin 路由组）&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;code&gt;/health&lt;/code&gt; 和 &lt;code&gt;/api/docs&lt;/code&gt; 为公开端点，仅经过 &lt;code&gt;Locale → Cors → SecurityFilter → RateLimit&lt;/code&gt;。&lt;/p&gt;
&lt;p&gt;安全增强：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;账号锁定&lt;/strong&gt;：连续 5 次登录失败，账号自动锁定 15 分钟，期间登录返回 429&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;并发会话限制&lt;/strong&gt;：同一用户最多 3 个有效 Token，超出时最旧 Token 自动加入黑名单&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;security.txt&lt;/strong&gt;：&lt;code&gt;GET /.well-known/security.txt&lt;/code&gt; 提供 RFC 9116 标准安全联系信息&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Nginx 安全配置&lt;/strong&gt;：参考 &lt;code&gt;docs/nginx-security.conf&lt;/code&gt; 提供完整的反向代理安全加固示例&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;认证&#34;&gt;&lt;a href=&#34;#认证&#34; class=&#34;headerlink&#34; title=&#34;认证&#34;&gt;&lt;/a&gt;认证&lt;/h3&gt;&lt;p&gt;登录与注册需要先通过&lt;strong&gt;点击验证码&lt;/strong&gt;校验：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;客户端请求 &lt;code&gt;POST /api/captcha/generate&lt;/code&gt; 获取验证码图片（base64 PNG）和文字目标列表&lt;/li&gt;
&lt;li&gt;用户按顺序点击图中对应文字位置，收集点击坐标 &lt;code&gt;[&amp;#123;x, y&amp;#125;, ...]&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;登录时一并提交 &lt;code&gt;captcha_key&lt;/code&gt; 和 &lt;code&gt;clicks&lt;/code&gt;，服务端先校验验证码再校验凭证&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;POST /api/auth/login&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Content-Type&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;application/json&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;username&amp;quot;: &amp;quot;admin&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;password&amp;quot;: &amp;quot;******&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;captcha_key&amp;quot;: &amp;quot;abc123...&amp;quot;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;quot;clicks&amp;quot;: [&amp;#123;&amp;quot;x&amp;quot;: 120, &amp;quot;y&amp;quot;: 85&amp;#125;, &amp;#123;&amp;quot;x&amp;quot;: 210, &amp;quot;y&amp;quot;: 140&amp;#125;, &amp;#123;&amp;quot;x&amp;quot;: 95, &amp;quot;y&amp;quot;: 170&amp;#125;]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;管理端后续接口需要 JWT 认证：&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Authorization&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;Bearer &amp;lt;token&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;登录成功后返回 access_token，有效期 2 小时；另返回 refresh_token，有效期 14 天。&lt;/p&gt;
&lt;p&gt;登出时 Token 加入 Redis 黑名单，有效期内不可复用。POST /admin/profile/logout&lt;/p&gt;
&lt;h3 id=&#34;敏感操作二次确认&#34;&gt;&lt;a href=&#34;#敏感操作二次确认&#34; class=&#34;headerlink&#34; title=&#34;敏感操作二次确认&#34;&gt;&lt;/a&gt;敏感操作二次确认&lt;/h3&gt;&lt;p&gt;删除用户、角色、权限等敏感操作需要在请求体中传入当前登录用户的 &lt;code&gt;password&lt;/code&gt; 进行身份二次确认：&lt;/p&gt;
&lt;figure class=&#34;highlight http&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;DELETE /admin/user/&amp;#123;id&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Content-Type&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;application/json&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;attribute&#34;&gt;Authorization&lt;/span&gt;&lt;span class=&#34;punctuation&#34;&gt;: &lt;/span&gt;Bearer &amp;lt;token&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123; &amp;quot;password&amp;quot;: &amp;quot;******&amp;quot; &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h2 id=&#34;API-列表&#34;&gt;&lt;a href=&#34;#API-列表&#34; class=&#34;headerlink&#34; title=&#34;API 列表&#34;&gt;&lt;/a&gt;API 列表&lt;/h2&gt;&lt;blockquote&gt;
&lt;p&gt;所有 &lt;code&gt;/api/*&lt;/code&gt; 接口需要在请求头中携带 &lt;code&gt;API-Version: v1&lt;/code&gt;（不传则默认 v1）。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;公开接口&#34;&gt;&lt;a href=&#34;#公开接口&#34; class=&#34;headerlink&#34; title=&#34;公开接口&#34;&gt;&lt;/a&gt;公开接口&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;路径&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/health&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;健康检查（DB/Redis/ES 状态）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/docs&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;OpenAPI 3.0 规范文档&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/captcha/generate&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;生成点击验证码&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/captcha/verify&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;校验点击验证码&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/login&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;登录（需 captcha）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/register&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;注册（需 captcha）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/api/auth/refresh&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;刷新令牌&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/metrics&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Prometheus 监控指标&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;h3 id=&#34;管理端接口（需-JWT-RBAC）&#34;&gt;&lt;a href=&#34;#管理端接口（需-JWT-RBAC）&#34; class=&#34;headerlink&#34; title=&#34;管理端接口（需 JWT + RBAC）&#34;&gt;&lt;/a&gt;管理端接口（需 JWT + RBAC）&lt;/h3&gt;&lt;div class=&#34;table-container&#34;&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;方法&lt;/th&gt;
&lt;th&gt;路径&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/dashboard&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;仪表盘数据（Redis 缓存 5 分钟）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;用户列表（分页 + 搜索）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;创建用户&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;用户详情&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新用户&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;DELETE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除用户（软删除，需密码确认）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user/batch/destroy&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;批量删除用户（需密码确认）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/user/batch/status&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;批量启用/禁用用户&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/role&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;角色列表&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/role&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;创建角色&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/role/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新角色&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;DELETE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/role/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除角色（需密码确认）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/permission&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;权限树&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/permission&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;创建权限&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/permission/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新权限&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;DELETE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/permission/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除权限（级联子权限，需密码确认）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/config&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;系统配置列表&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/config&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;创建配置项&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/config/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新配置项&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;DELETE&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/config/&amp;#123;id&amp;#125;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;删除配置项（需密码确认）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;GET&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/log&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;操作日志（分页 + 筛选）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/profile&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;更新个人信息&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;PUT&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/profile/password&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;修改密码&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/profile/logout&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;登出（JWT 黑名单）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/export/excel&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;导出 Excel&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;POST&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;/admin/export/pdf&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;导出 PDF&lt;/td&gt;
